def _first_present_parameter(parameters: dict[str, Any], keys: tuple[str, ...]) -> tuple[str, Any] | None:
    for candidate in keys:
        if candidate in parameters:
            return candidate, parameters[candidate]
    return None


def _op_accepts_source_alias(op_name: str) -> bool:
    return op_name in _SOURCE_REPLACEMENT_OPS or "source" in _REQUIRED_PARAMS.get(op_name, ())


def _op_accepts_target_alias(op_name: str) -> bool:
    return op_name in _TARGET_REPLACEMENT_OPS or "target" in _REQUIRED_PARAMS.get(op_name, ())


def _normalized_operation_parameters(op: ShapeOp) -> dict[str, Any]:
    parameters = dict(op.parameters)
    for canonical, aliases in _PARAMETER_ALIASES_BY_OP.get(op.op, {}).items():
        if canonical in parameters:
            continue
        present = _first_present_parameter(parameters, aliases)
        if present is not None:
            parameters[canonical] = present[1]
    if "source" not in parameters and _op_accepts_source_alias(op.op):
        present = _first_present_parameter(parameters, _SOURCE_PARAMETER_ALIASES)
        if present is not None:
            parameters["source"] = present[1]
    if "target" not in parameters and _op_accepts_target_alias(op.op):
        present = _first_present_parameter(parameters, _TARGET_PARAMETER_ALIASES)
        if present is not None:
            parameters["target"] = present[1]
    return parameters


def _has_required_param_alias(op_name: str, parameters: dict[str, Any], key: str) -> bool:
    if key in parameters:
        return True
    if _first_present_parameter(parameters, _PARAMETER_ALIASES_BY_OP.get(op_name, {}).get(key, ())) is not None:
        return True
    if key == "source" and _op_accepts_source_alias(op_name):
        return _first_present_parameter(parameters, _SOURCE_PARAMETER_ALIASES) is not None
    if key == "target" and _op_accepts_target_alias(op_name):
        return _first_present_parameter(parameters, _TARGET_PARAMETER_ALIASES) is not None
    if op_name == "solid.extruded_profile":
        if key == "profile_polygon":
            return (
                "profile_points" in parameters
                or "profile_curve" in parameters
                or "cross_section_curve" in parameters
                or "curve" in parameters
            )
        if key == "extrude_height_cm":
            return "height_cm" in parameters or "height" in parameters
    if op_name == "solid.revolved_profile" and key == "profile_points":
        return "profile_curve" in parameters or "curve" in parameters
    if op_name in {"solid.swept_profile", "sop.sweep"}:
        if key == "cross_section":
            return "cross_section_curve" in parameters or "profile_curve" in parameters or "curve" in parameters
        if key == "sweep_path":
            return "path" in parameters or "sweep_curve" in parameters or "path_curve" in parameters
    if op_name == "sop.boolean" and key == "source":
        return "sources" in parameters
    if op_name == "sop.helical_sweep" and key == "tube_radius_cm":
        return (
            "cross_section" in parameters
            or "cross_section_curve" in parameters
            or "profile_curve" in parameters
            or "curve" in parameters
        )
    if op_name == "sop.polywire":
        if key == "radius_cm":
            return (
                "cross_section" in parameters
                or "cross_section_curve" in parameters
                or "profile_curve" in parameters
                or "radii_cm" in parameters
                or "radius_profile_cm" in parameters
                or "radius_values_cm" in parameters
                or ("start_radius_cm" in parameters and "end_radius_cm" in parameters)
            )
        if key == "path":
            return "path_curve" in parameters or "sweep_curve" in parameters or "curve" in parameters
    if op_name == "sop.copy_to_points" and key == "points":
        return any(
            candidate in parameters
            for candidate in (
                "points_curve",
                "point_curve",
                "path_curve",
                "sweep_curve",
                "curve",
            )
        )
    if op_name == "solid.curved_tube" and key in {"radius_cm", "angle_degrees"}:
        return "path" in parameters or "path_curve" in parameters or "sweep_curve" in parameters or "curve" in parameters
    if op_name == "sop.polyextrude":
        if "source" in parameters and key in {"profile_polygon", "extrude_height_cm"}:
            return True
        if key == "profile_polygon":
            return "profile_points" in parameters
        if key == "extrude_height_cm":
            return "height_cm" in parameters or "height" in parameters or "distance_cm" in parameters
    return False


def validate_op(op: ShapeOp) -> tuple[bool, list[str]]:
    """Return ``(is_valid, diagnostics)`` for ``op``.

    Checks:

    1. ``op.op`` is a member of :data:`ALL_OPS`. If not, returns
       ``(False, ["unsupported_v2_op"])`` and no further checks run.
    2. Every key in ``_REQUIRED_PARAMS[op.op]`` is present in
       ``op.parameters``. Each missing key yields a diagnostic of the
       form ``"missing_required_param: <key>"``.

    Diagnostics are returned as a list of strings in declaration order.
    """
    if op.op not in ALL_OPS:
        return (False, ["unsupported_v2_op"])

    diagnostics: list[str] = []
    required = _REQUIRED_PARAMS.get(op.op, ())
    parameters = op.parameters if isinstance(op.parameters, dict) else {}
    for key in required:
        if not _has_required_param_alias(op.op, parameters, key):
            diagnostics.append(f"missing_required_param: {key}")
    return (not diagnostics, diagnostics)


def _float_param(parameters: dict[str, Any], key: str) -> float:
    value = parameters[key]
    if isinstance(value, bool):
        raise ValueError(f"parameter '{key}' must be numeric")
    try:
        converted = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"parameter '{key}' must be numeric") from exc
    if not math.isfinite(converted):
        raise ValueError(f"parameter '{key}' must be finite")
    return converted


def _axis_param(parameters: dict[str, Any]) -> str:
    axis = parameters.get("axis", "y")
    if axis not in {"x", "y", "z"}:
        raise ValueError("parameter 'axis' must be one of: x, y, z")
    return str(axis)


def _center_param(parameters: dict[str, Any]) -> tuple[float, float, float]:
    center = parameters.get("center", (0.0, 0.0, 0.0))
    return _point_list_param(
        {"center": [center]},
        "center",
        dimensions=3,
        min_points=1,
    )[0]


def _string_param(
    parameters: dict[str, Any],
    key: str,
    *,
    allowed: set[str] | None = None,
) -> str:
    value = parameters[key]
    if not isinstance(value, str) or not value:
        raise ValueError(f"parameter '{key}' must be a non-empty string")
    if allowed is not None and value not in allowed:
        allowed_values = ", ".join(sorted(allowed))
        raise ValueError(f"parameter '{key}' must be one of: {allowed_values}")
    return value


def _int_param(parameters: dict[str, Any], key: str) -> int:
    value = _float_param(parameters, key)
    if not value.is_integer():
        raise ValueError(f"parameter '{key}' must be an integer")
    return int(value)


def _optional_bounded_int_param(
    parameters: dict[str, Any],
    keys: tuple[str, ...],
    *,
    minimum: int,
    maximum: int,
) -> tuple[int | None, int | None, str | None]:
    for key in keys:
        if key not in parameters:
            continue
        requested = _int_param(parameters, key)
        if requested < minimum:
            raise ValueError(f"parameter '{key}' must be >= {minimum}")
        return min(requested, maximum), requested, key
    return None, None, None


def _attach_tessellation_modifier(
    record: dict[str, Any],
    payload: dict[str, Any],
) -> dict[str, Any]:
    modifier = {
        "schema": "lathe.shape_ir_v2.tessellation_modifier.v1",
        **payload,
    }
    record["v2_tessellation_modifier"] = modifier
    metadata = record.get("semantic_metadata")
    if isinstance(metadata, dict):
        metadata = dict(metadata)
    elif metadata:
        metadata = {"raw_semantic_metadata": _metadata_safe_value(metadata)}
    else:
        metadata = {}
    metadata["v2_tessellation_modifier"] = modifier
    record["semantic_metadata"] = metadata
    tags = list(record.get("tags") or [])
    for tag in payload.get("tags", ()):
        tag_text = str(tag)
        if tag_text and tag_text not in tags:
            tags.append(tag_text)
    record["tags"] = tags
    return record


def _point_list_param(
    parameters: dict[str, Any],
    key: str,
    *,
    dimensions: int,
    min_points: int,
) -> tuple[tuple[float, ...], ...]:
    value = parameters[key]
    if not isinstance(value, (list, tuple)):
        raise ValueError(f"parameter '{key}' must be a sequence of points")
    points: list[tuple[float, ...]] = []
    for index, point in enumerate(value):
        if not isinstance(point, (list, tuple)) or len(point) != dimensions:
            raise ValueError(
                f"parameter '{key}' point {index} must have {dimensions} numeric values"
            )
        converted: list[float] = []
        for coord_index, coord in enumerate(point):
            if isinstance(coord, bool):
                raise ValueError(
                    f"parameter '{key}' point {index}.{coord_index} must be numeric"
                )
            try:
                number = float(coord)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"parameter '{key}' point {index}.{coord_index} must be numeric"
                ) from exc
            if not math.isfinite(number):
                raise ValueError(
                    f"parameter '{key}' point {index}.{coord_index} must be finite"
                )
            converted.append(number)
        points.append(tuple(converted))
    if len(points) < min_points:
        raise ValueError(f"parameter '{key}' must contain at least {min_points} points")
    return tuple(points)


def _fixed_float_tuple_param(
    parameters: dict[str, Any],
    key: str,
    *,
    count: int,
) -> tuple[float, ...]:
    value = parameters[key]
    if not isinstance(value, (list, tuple)) or len(value) != count:
        raise ValueError(f"parameter '{key}' must contain exactly {count} numeric values")
    converted: list[float] = []
    for index, item in enumerate(value):
        if isinstance(item, bool):
            raise ValueError(f"parameter '{key}' item {index} must be numeric")
        try:
            number = float(item)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"parameter '{key}' item {index} must be numeric") from exc
        if not math.isfinite(number):
            raise ValueError(f"parameter '{key}' item {index} must be finite")
        converted.append(number)
    return tuple(converted)


def _round_cross_section(radius: float, segments: int = 10) -> tuple[tuple[float, float], ...]:
    """Return a deterministic circular cross-section polygon."""
    radius = max(float(radius), 0.001)
    segments = max(6, min(32, int(segments)))
    return tuple(
        (
            math.cos(math.tau * index / segments) * radius,
            math.sin(math.tau * index / segments) * radius,
        )
        for index in range(segments)
    )


def _copy_with_tags(record: _V1Record, *tags: str) -> _V1Record:
    copied = dict(record)
    existing_tags = list(copied.get("tags") or [])
    copied["tags"] = [*existing_tags, *tags]
    return copied


def _record_with_source(
    op: ShapeOp,
    *tags: str,
    source_key: str = "source",
    geometry_kernel: Any | None = None,
) -> _V1Record:
    record = _copy_with_tags(
        _single_source_record_from_param(
            op.parameters[source_key],
            geometry_kernel=geometry_kernel,
        ),
        *tags,
    )
    record["part"] = op.target or record.get("part") or "body"
    record["v2_source_op"] = record.get("v2_op")
    record["v2_op"] = op.op
    record["v2_purpose"] = op.purpose
    return record


_BOOLEAN_TOOL_PARAM_KEYS = (
    "tool",
    "cutter",
    "operand",
    "right",
    "rhs",
    "subtrahend",
    "mask",
)


def _boolean_tool_param_key(parameters: dict[str, Any]) -> str | None:
    for key in _BOOLEAN_TOOL_PARAM_KEYS:
        if key in parameters:
            return key
    return None


def _boolean_source_sequence(parameters: dict[str, Any]) -> tuple[Any, ...] | None:
    raw_sources: Any
    if "sources" in parameters:
        raw_sources = parameters["sources"]
    else:
        raw_sources = parameters.get("source")
        if not isinstance(raw_sources, (list, tuple)):
            return None
    if not isinstance(raw_sources, (list, tuple)) or not raw_sources:
        raise ValueError("parameter 'sources' must be a non-empty sequence")
    return tuple(raw_sources)


def _optional_boolean_bevel_width(parameters: dict[str, Any]) -> float:
    for key in (
        "bevel_width_cm",
        "polybevel_width_cm",
        "edge_bevel_width_cm",
        "chamfer_width_cm",
        "bevel_radius_cm",
    ):
        if key in parameters:
            width = _optional_float_param(parameters, key, 0.0)
            if width < 0.0:
                raise ValueError(f"parameter '{key}' must be >= 0")
            return float(width)
    return 0.0


def _optional_boolean_bevel_segments(parameters: dict[str, Any]) -> int:
    for key in (
        "bevel_segments",
        "polybevel_segments",
        "chamfer_segments",
        "segments",
    ):
        if key in parameters:
            return _optional_int_param(parameters, key, 1, minimum=1)
    return 1


def _with_boolean_polybevel_if_requested(
    record: dict[str, Any],
    *,
    op: ShapeOp,
    operation: str,
    blend_mode: str,
    seam_group: str,
) -> dict[str, Any]:
    if blend_mode not in {"subtract", "intersect"} and operation != "union":
        return record
    width = _optional_boolean_bevel_width(op.parameters)
    if width <= 0.0:
        return record
    return _with_targeted_polybevel(
        record,
        seam_group=seam_group,
        width=width,
        segments=_optional_boolean_bevel_segments(op.parameters),
    )


def _boolean_operand_record(
    op: ShapeOp,
    source: Any,
    *,
    operation: str,
    blend_mode: str,
    geometry_kernel: Any | None = None,
) -> _V1Record:
    record = _copy_with_tags(
        _single_source_record_from_param(source, geometry_kernel=geometry_kernel),
        _op_tag_token(op.op),
        f"boolean_{operation}",
    )
    record["v2_source_op"] = record.get("v2_op")
    record["v2_op"] = op.op
    record["v2_purpose"] = op.purpose
    record["blend_mode"] = blend_mode
    if (
        blend_mode in {"subtract", "intersect"}
        or op.parameters.get("seam_group")
        or op.parameters.get("seam")
    ):
        seam_group = _seam_group_name(op, f"{operation}_seam")
        _with_boolean_seam(
            record,
            op=op,
            operation=operation,
            seam_group=seam_group,
        )
        _with_boolean_polybevel_if_requested(
            record,
            op=op,
            operation=operation,
            blend_mode=blend_mode,
            seam_group=seam_group,
        )
    return _attach_group_lists_to_v2_metadata(record)


def _boolean_operand_records(
    op: ShapeOp,
    source: Any,
    *,
    operation: str,
    blend_mode: str,
    geometry_kernel: Any | None = None,
) -> tuple[_V1Record, ...]:
    record = _boolean_operand_record(
        op,
        source,
        operation=operation,
        blend_mode=blend_mode,
        geometry_kernel=geometry_kernel,
    )
    if not record.get("v2_context_aggregate"):
        return (record,)
    context_children = tuple(
        child
        for child in _context_records_for_aggregate((record,))
        if not child.get("v2_context_aggregate")
    )
    if not context_children:
        return (record,)
    records: list[_V1Record] = []
    root_tags = [str(tag) for tag in record.get("tags", []) if str(tag)]
    for child_index, child in enumerate(context_children):
        child_record = _boolean_operand_record(
            op,
            child,
            operation=operation,
            blend_mode=blend_mode,
            geometry_kernel=geometry_kernel,
        )
        child_record["tags"] = list(
            dict.fromkeys(
                [
                    *root_tags,
                    *[str(tag) for tag in child_record.get("tags", []) if str(tag)],
                    "source_context_boolean_child",
                    f"source_context_child_{child_index}",
                ]
            )
        )
        boolean_metadata = dict(child_record.get("v2_boolean_context") or {})
        boolean_metadata["source_context_aggregate"] = True
        boolean_metadata["source_context_child_index"] = child_index
        boolean_metadata["source_context_record_count"] = len(context_children)
        boolean_metadata["source_context_root_part"] = str(record.get("part") or "")
        child_record["v2_boolean_context"] = boolean_metadata
        records.append(_attach_group_lists_to_v2_metadata(child_record))
    return tuple(records)


def _common_context_root(records: tuple[_V1Record, ...], *, fallback: str) -> str:
    parts = [
        str(record.get("part") or "").strip()
        for record in records
        if str(record.get("part") or "").strip()
    ]
    if parts and all(part == parts[0] for part in parts):
        return parts[0]
    components = [
        str(record.get("component") or "").strip()
        for record in records
        if str(record.get("component") or "").strip()
    ]
    if components and all(component == components[0] for component in components):
        return components[0]
    return fallback


def _single_source_record_from_param(
    source: Any,
    *,
    geometry_kernel: Any | None = None,
) -> _V1Record:
    """Return one v1 primitive record from a copy-to-points source parameter."""
    if isinstance(source, ShapeOp):
        source_op = source
    elif isinstance(source, dict) and "op" in source:
        source_parameters = source.get("parameters", {})
        if not isinstance(source_parameters, dict):
            raise ValueError("parameter 'source.parameters' must be a dict")
        source_op = ShapeOp(
            op=str(source["op"]),
            target=source.get("target"),
            parameters=source_parameters,
            purpose=source.get("purpose"),
        )
    elif isinstance(source, dict) and "primitive_type" in source:
        record = dict(source)
        if record.get("v2_context_aggregate") and geometry_kernel is not None:
            return _kernel_record_for_context_aggregate(record, geometry_kernel=geometry_kernel)
        return record
    elif isinstance(source, (list, tuple)):
        if not source:
            raise ValueError("parameter 'source' must be a non-empty sequence")
        records = tuple(
            _single_source_record_from_param(
                item,
                geometry_kernel=geometry_kernel,
            )
            for item in source
        )
        root = _common_context_root(records, fallback="compound_source")
        aggregate = _aggregate_context_record(root, records)
        if geometry_kernel is not None:
            return _kernel_record_for_context_aggregate(
                aggregate,
                geometry_kernel=geometry_kernel,
            )
        return aggregate
    else:
        raise ValueError(
            "parameter 'source' must be a v1 primitive record or ShapeOp-like dict"
        )

    required = _REQUIRED_PARAMS.get(source_op.op, ())
    missing = [
        key
        for key in required
        if not _has_required_param_alias(source_op.op, source_op.parameters, key)
    ]
    if missing:
        raise ValueError(
            "parameter 'source' is missing required parameter(s): " + ", ".join(missing)
        )
    lowerer = _V1_LOWERERS.get(source_op.op)
    if lowerer is None:
        raise ValueError(f"parameter 'source' op {source_op.op!r} is not v1-lowerable")
    lowered = _lower_op_to_v1(source_op, lowerer, geometry_kernel=geometry_kernel)
    records = _normalize_lowering(lowered)
    if len(records) != 1:
        if geometry_kernel is not None:
            root = str(source_op.target or source_op.op.replace(".", "_") or "compound_source")
            aggregate = _aggregate_context_record(root, records)
            return _kernel_record_for_context_aggregate(aggregate, geometry_kernel=geometry_kernel)
        raise ValueError("parameter 'source' must lower to exactly one v1 primitive")
    return records[0]


def _lower_op_to_v1(
    op: ShapeOp,
    lowerer: _V1Lowerer,
    *,
    geometry_kernel: Any | None,
) -> _V1Lowering:
    normalized_op = ShapeOp(
        op=op.op,
        target=op.target,
        parameters=_normalized_operation_parameters(op),
        purpose=op.purpose,
    )
    if normalized_op.op in _KERNEL_CONTEXT_OPS:
        return lowerer(normalized_op, geometry_kernel=geometry_kernel)
    return lowerer(normalized_op)


def _normalize_lowering(lowered: _V1Lowering) -> tuple[_V1Record, ...]:
    if isinstance(lowered, tuple):
        return lowered
    return (lowered,)


def _lowering_exception_diagnostic(op: ShapeOp, exc: Exception) -> dict[str, Any]:
    details = getattr(exc, "details", None)
    code = str(getattr(exc, "code", "") or "")
    text = str(exc)
    if op.op in _KERNEL_CONTEXT_OPS and (
        isinstance(details, dict)
        or code.startswith("kernel_program")
        or "kernel" in text.lower()
    ):
        diagnostic: dict[str, Any] = {
            "code": "kernel_program_lowering_failed",
            "op": op.op,
            "reason": text,
            "exception_type": type(exc).__name__,
        }
        if code:
            diagnostic["kernel_error_code"] = code
        if isinstance(details, dict):
            diagnostic["details"] = dict(details)
        return diagnostic
    return {
        "code": "parameter_type_mismatch",
        "op": op.op,
        "reason": text,
    }


_IMMUTABLE_LEAF_TYPES: tuple[type, ...] = (str, int, float, bool, type(None), bytes, frozenset)


def _metadata_safe_value(value: Any) -> Any:
    """Recursively safe-copy a metadata structure.

    Recurses into dict / list / tuple to produce a fresh outer
    container (so callers can mutate without affecting the source).
    For leaves, returns immutable types AS-IS — ``deepcopy`` of a
    string / int / float / bool / None is wasted work, and this
    function was previously called ~22,500 times per v1 record on
    the lower_to_v1 hot path, costing 89 % of build time on the
    industrial_crate synthesizer path (188s of 189s total per
    cProfile run). Mutable leaves still go through ``deepcopy`` to
    preserve the original semantic.
    """
    if isinstance(value, dict):
        return {str(key): _metadata_safe_value(item) for key, item in value.items()}
    if isinstance(value, tuple):
        return [_metadata_safe_value(item) for item in value]
    if isinstance(value, list):
        return [_metadata_safe_value(item) for item in value]
    if isinstance(value, _IMMUTABLE_LEAF_TYPES):
        # Immutable — sharing is safe.
        return value
    # Mutable / unknown leaf type — preserve the prior deepcopy semantics.
    return deepcopy(value)


def _v2_operation_token(record: _V1Record) -> str:
    raw = str(record.get("v2_op") or record.get("v2_source_op") or "shape_op")
    return "".join(char if char.isalnum() else "_" for char in raw).strip("_") or "shape_op"


def _looks_like_temporary_kernel_operation_id(value: str) -> bool:
    text = str(value or "")
    return text.startswith(("operand:", "program:")) or ".instance_" in text


def _promote_kernel_operation_records(
    records: list[Any],
    *,
    final_operation_id: str,
    final_operation: str,
) -> list[Any]:
    promoted_records: list[Any] = []
    for record in records:
        if not isinstance(record, dict):
            promoted_records.append(record)
            continue
        current_id = str(record.get("operation_id") or "")
        if (
            str(record.get("operation") or "") == final_operation
            and current_id != final_operation_id
            and _looks_like_temporary_kernel_operation_id(current_id)
        ):
            promoted_records.append(
                {
                    **dict(record),
                    "operation_id": final_operation_id,
                    "previous_operation_id": current_id,
                    "operation_id_promoted_to_v2": True,
                }
            )
        else:
            promoted_records.append(dict(record))
    return promoted_records


def _promote_kernel_handoff_operation_records(
    metadata: dict[str, Any],
    *,
    final_operation_id: str,
    final_operation: str,
) -> dict[str, Any]:
    promoted = dict(metadata)
    for handoff_key in (
        "kernel_program_semantic_handoff",
        "lathe_kernel_program_semantic_handoff",
    ):
        handoff = promoted.get(handoff_key)
        if not isinstance(handoff, dict):
            continue
        records = handoff.get("operation_records")
        if not isinstance(records, list):
            continue
        promoted_records = _promote_kernel_operation_records(
            records,
            final_operation_id=final_operation_id,
            final_operation=final_operation,
        )
        promoted[handoff_key] = {
            **dict(handoff),
            "operation_records": promoted_records,
            "operation_record_count": len(promoted_records),
        }
    return promoted


def _operation_id_mentions_final_operation(value: str, final_operation: str) -> bool:
    if not final_operation:
        return True
    token = "".join(char if char.isalnum() else "_" for char in final_operation).strip("_")
    return bool(token and token in str(value))


def _promote_kernel_face_operation_summary_id(
    metadata: dict[str, Any],
    *,
    final_operation_id: str,
    final_operation: str,
    previous_operation_id: str | None = None,
) -> tuple[dict[str, Any], str | None]:
    face_summary = metadata.get("face_operation_summary")
    if not isinstance(face_summary, dict):
        return metadata, None
    operations = face_summary.get("operations")
    if not isinstance(operations, dict) or len(operations) != 1:
        return metadata, None
    summary_operation_id = str(next(iter(operations.keys())))
    if summary_operation_id == final_operation_id:
        return metadata, None
    if previous_operation_id is not None and summary_operation_id != previous_operation_id:
        return metadata, None
    if not _looks_like_temporary_kernel_operation_id(summary_operation_id):
        return metadata, None
    if not _operation_id_mentions_final_operation(summary_operation_id, final_operation):
        return metadata, None

    count = operations[next(iter(operations.keys()))]
    summary = {
        **dict(face_summary),
        "operations": {final_operation_id: count},
        "face_operation_id_promoted_to_v2": True,
        "previous_face_operation_id": summary_operation_id,
    }
    promoted = {
        **metadata,
        "face_operation_summary": summary,
        "face_operation_id_promoted_to_v2": True,
        "previous_face_operation_id": summary_operation_id,
    }
    for attribution_key in (
        "lathe_kernel_program_face_operation_attribution",
        "kernel_program_face_operation_attribution",
    ):
        attribution = promoted.get(attribution_key)
        if isinstance(attribution, dict):
            promoted[attribution_key] = {
                **dict(attribution),
                "operation_id_promoted_to_v2": True,
                "previous_face_operation_id": summary_operation_id,
                "promoted_face_operation_id": final_operation_id,
            }
    return promoted, summary_operation_id


def _promote_kernel_result_face_operation_id(
    metadata: dict[str, Any],
    *,
    final_operation_id: str,
    final_operation: str,
) -> dict[str, Any]:
    kernel_metadata = metadata.get(_KERNEL_RESULT_METADATA_KEY)
    if not isinstance(kernel_metadata, dict):
        return metadata
    for record_key in (
        "kernel_program_semantic_operation_records",
        "semantic_operation_records",
    ):
        records = kernel_metadata.get(record_key)
        if not isinstance(records, list):
            continue
        promoted_records = _promote_kernel_operation_records(
            records,
            final_operation_id=final_operation_id,
            final_operation=final_operation,
        )
        kernel_metadata = {**kernel_metadata, record_key: promoted_records}
        metadata[_KERNEL_RESULT_METADATA_KEY] = kernel_metadata
    kernel_metadata = _promote_kernel_handoff_operation_records(
        kernel_metadata,
        final_operation_id=final_operation_id,
        final_operation=final_operation,
    )
    metadata[_KERNEL_RESULT_METADATA_KEY] = kernel_metadata
    kernel_metadata, _ = _promote_kernel_face_operation_summary_id(
        kernel_metadata,
        final_operation_id=final_operation_id,
        final_operation=final_operation,
    )
    metadata[_KERNEL_RESULT_METADATA_KEY] = kernel_metadata
    face_ids = kernel_metadata.get("face_operation_ids")
    if not isinstance(face_ids, list) or not face_ids:
        return metadata
    unique_ids = sorted({str(value) for value in face_ids if str(value)})
    if len(unique_ids) != 1:
        return metadata
    previous_id = unique_ids[0]
    if previous_id == final_operation_id or not _looks_like_temporary_kernel_operation_id(previous_id):
        return metadata

    promoted = dict(kernel_metadata)
    promoted["face_operation_ids"] = [
        final_operation_id if str(value) == previous_id else str(value)
        for value in face_ids
    ]
    promoted, _ = _promote_kernel_face_operation_summary_id(
        promoted,
        final_operation_id=final_operation_id,
        final_operation=final_operation,
        previous_operation_id=previous_id,
    )
    for record_key in (
        "kernel_program_semantic_operation_records",
        "semantic_operation_records",
    ):
        records = promoted.get(record_key)
        if not isinstance(records, list):
            continue
        promoted[record_key] = [
            {
                **dict(record),
                **(
                    {"operation_id": final_operation_id}
                    if str(record.get("operation_id") or "") == previous_id
                    else {}
                ),
            }
            if isinstance(record, dict)
            else record
            for record in records
        ]
    attribution = promoted.get("lathe_kernel_program_face_operation_attribution")
    if isinstance(attribution, dict):
        promoted["lathe_kernel_program_face_operation_attribution"] = {
            **dict(attribution),
            "operation_id_promoted_to_v2": True,
            "previous_face_operation_id": previous_id,
            "promoted_face_operation_id": final_operation_id,
        }
    promoted["face_operation_id_promoted_to_v2"] = True
    promoted["previous_face_operation_id"] = previous_id
    metadata[_KERNEL_RESULT_METADATA_KEY] = promoted
    return metadata


def _promote_v2_provenance(
    record: _V1Record,
    *,
    op_index: int,
    record_index: int,
) -> _V1Record:
    copied = dict(record)
    metadata = copied.get("semantic_metadata")
    if isinstance(metadata, dict):
        metadata = deepcopy(metadata)
    elif metadata:
        metadata = {"raw_semantic_metadata": _metadata_safe_value(metadata)}
    else:
        metadata = {}

    v2_metadata = metadata.get(_V2_PROVENANCE_METADATA_KEY)
    if isinstance(v2_metadata, dict):
        v2_metadata = dict(v2_metadata)
    else:
        v2_metadata = {}

    v2_metadata.setdefault("operation_index", op_index)
    v2_metadata.setdefault("record_index", record_index)
    v2_metadata.setdefault(
        "operation_id",
        f"{op_index:04d}:{_v2_operation_token(copied)}:{record_index:02d}",
    )
    for key in ("part", "component", "region"):
        value = copied.get(key)
        if value not in (None, "", (), [], {}):
            v2_metadata.setdefault(key, _metadata_safe_value(value))

    for key, value in copied.items():
        if key.startswith("v2_") and value not in (None, "", (), [], {}):
            v2_metadata.setdefault(key, _metadata_safe_value(value))

    metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    metadata = _promote_kernel_result_face_operation_id(
        metadata,
        final_operation_id=str(v2_metadata["operation_id"]),
        final_operation=str(v2_metadata.get("v2_op") or ""),
    )
    copied["semantic_metadata"] = metadata
    return copied


def _target_source_keys(target: str | None) -> tuple[str, ...]:
    if not target:
        return ()
    raw_parts = [part for part in str(target).split(".") if part]
    keys: list[str] = []
    for count in range(len(raw_parts), 0, -1):
        keys.append(".".join(raw_parts[:count]))
    return tuple(keys)


def _record_center_tuple(record: _V1Record) -> tuple[float, float, float]:
    raw_center = record.get("center")
    if isinstance(raw_center, (list, tuple)) and len(raw_center) == 3:
        return tuple(float(value) for value in raw_center)
    return (0.0, 0.0, 0.0)


def _record_mesh_vertices_are_world_space(record: _V1Record) -> bool:
    space = record.get("mesh_vertices_space")
    if space is None:
        metadata = record.get("semantic_metadata")
        if isinstance(metadata, dict):
            space = metadata.get("mesh_vertices_space")
    if str(space or "").lower() == "world_cm":
        return True
    return str(record.get("primitive_type") or "") == "kernel_primitive_mesh"


def _record_mesh_vertex_bounds(
    record: _V1Record,
) -> tuple[tuple[float, float, float], tuple[float, float, float]] | None:
    vertices = record.get("mesh_vertices")
    if not isinstance(vertices, (list, tuple)) or not vertices:
        return None
    points: list[tuple[float, float, float]] = []
    for vertex in vertices:
        if not isinstance(vertex, (list, tuple)) or len(vertex) != 3:
            return None
        try:
            points.append((float(vertex[0]), float(vertex[1]), float(vertex[2])))
        except (TypeError, ValueError):
            return None
    if not points:
        return None
    center = (
        (0.0, 0.0, 0.0)
        if _record_mesh_vertices_are_world_space(record)
        else _record_center_tuple(record)
    )
    mins = tuple(min(point[axis] for point in points) + center[axis] for axis in range(3))
    maxs = tuple(max(point[axis] for point in points) + center[axis] for axis in range(3))
    return mins, maxs


def _record_placement_center(record: _V1Record) -> tuple[float, float, float]:
    mesh_bounds = _record_mesh_vertex_bounds(record)
    if mesh_bounds is not None:
        mins, maxs = mesh_bounds
        return tuple((mins[axis] + maxs[axis]) * 0.5 for axis in range(3))
    if str(record.get("primitive_type") or "") == "component_assembly":
        assembly_bounds = _component_assembly_record_bounds(record)
        if assembly_bounds is not None:
            mins, maxs = assembly_bounds
            return tuple((mins[axis] + maxs[axis]) * 0.5 for axis in range(3))
    return _record_center_tuple(record)


def _profile_2d_extents(value: Any) -> tuple[float, float] | None:
    if not isinstance(value, (list, tuple)) or not value:
        return None
    try:
        first = [float(point[0]) for point in value]
        second = [float(point[1]) for point in value]
    except (TypeError, ValueError, IndexError):
        return None
    return (max(first) - min(first), max(second) - min(second))


def _component_assembly_record_bounds(
    record: _V1Record,
    *,
    _depth: int = 0,
) -> tuple[tuple[float, float, float], tuple[float, float, float]] | None:
    if _depth >= 8:
        return None
    components = record.get("assembly_primitives")
    if not isinstance(components, (list, tuple)) or not components:
        return None

    bounds: list[tuple[tuple[float, float, float], tuple[float, float, float]]] = []
    for component in components:
        if not isinstance(component, dict):
            continue
        if str(component.get("primitive_type") or "") == "component_assembly":
            component_bounds = _component_assembly_record_bounds(component, _depth=_depth + 1)
        else:
            component_bounds = _record_mesh_vertex_bounds(component)
            if component_bounds is None:
                try:
                    center = _record_center_tuple(component)
                    extents = _record_context_extents(component)
                except (TypeError, ValueError, IndexError):
                    continue
                half = tuple(value * 0.5 for value in extents)
                component_bounds = (
                    tuple(center[axis] - half[axis] for axis in range(3)),
                    tuple(center[axis] + half[axis] for axis in range(3)),
                )
        if component_bounds is not None:
            bounds.append(component_bounds)
    if not bounds:
        return None
    mins = tuple(min(item[0][axis] for item in bounds) for axis in range(3))
    maxs = tuple(max(item[1][axis] for item in bounds) for axis in range(3))
    return mins, maxs


def _record_context_extents(record: _V1Record) -> tuple[float, float, float]:
    mesh_bounds = _record_mesh_vertex_bounds(record)
    if mesh_bounds is not None:
        mins, maxs = mesh_bounds
        return tuple(max(maxs[axis] - mins[axis], 1e-6) for axis in range(3))

    extents = record.get("extents")
    if isinstance(extents, (list, tuple)) and len(extents) == 3:
        return tuple(max(float(value), 1e-6) for value in extents)

    primitive_type = str(record.get("primitive_type") or "")
    if primitive_type in {"box", "subdivision_box"}:
        return (1.0, 1.0, 1.0)
    if primitive_type == "sphere" and record.get("radius") is not None:
        radius = max(float(record["radius"]), 1e-6)
        return (radius * 2.0, radius * 2.0, radius * 2.0)
    if primitive_type == "cylinder" and record.get("radius") is not None:
        radius = max(float(record["radius"]), 1e-6)
        height = max(float(record.get("height") or radius * 2.0), 1e-6)
        axis = str(record.get("axis") or "y")
        values = [radius * 2.0, radius * 2.0, radius * 2.0]
        values[_axis_index(axis)] = height
        return (values[0], values[1], values[2])
    if primitive_type == "threaded_cylinder" and record.get("radius") is not None:
        radius = max(
            float(record["radius"]) + float(record.get("thread_depth") or 0.0),
            1e-6,
        )
        height = max(float(record.get("height") or radius * 2.0), 1e-6)
        axis = str(record.get("axis") or "y")
        values = [radius * 2.0, radius * 2.0, radius * 2.0]
        values[_axis_index(axis)] = height
        return (values[0], values[1], values[2])
    if primitive_type == "component_assembly":
        assembly_bounds = _component_assembly_record_bounds(record)
        if assembly_bounds is not None:
            mins, maxs = assembly_bounds
            return tuple(max(maxs[axis] - mins[axis], 1e-6) for axis in range(3))
    if primitive_type == "socket":
        width = max(float(record.get("width") or record.get("clearance") or 1.0), 1e-6)
        height = max(float(record.get("height") or record.get("clearance") or width), 1e-6)
        depth = max(float(record.get("depth") or record.get("clearance") or 1.0), 1e-6)
        axis = str(record.get("axis") or "z")
        values = [width, height, depth]
        if axis == "x":
            values = [depth, height, width]
        elif axis == "y":
            values = [width, depth, height]
        return (values[0], values[1], values[2])
    if primitive_type == "weld_seam":
        if record.get("radius") is not None:
            radius = max(float(record.get("radius")), 1e-6)
        else:
            radius = max(float(record.get("width") or 1.0) * 0.5, 1e-6)
        if record.get("sweep_path") is not None:
            points = record.get("sweep_path")
            if isinstance(points, (list, tuple)) and points:
                try:
                    coords = [
                        (float(point[0]), float(point[1]), float(point[2]))
                        for point in points
                    ]
                    mins = tuple(min(point[index] for point in coords) for index in range(3))
                    maxs = tuple(max(point[index] for point in coords) for index in range(3))
                    return tuple(max(maxs[index] - mins[index] + radius * 2.0, 1e-6) for index in range(3))
                except (TypeError, ValueError, IndexError):
                    pass
        length = max(float(record.get("length") or record.get("extrude_height") or radius * 2.0), 1e-6)
        axis = str(record.get("axis") or "x")
        values = [radius * 2.0, radius * 2.0, radius * 2.0]
        values[_axis_index(axis)] = length
        return (values[0], values[1], values[2])
    if primitive_type == "edge_chip_set":
        source_extents = record.get("source_extents")
        if isinstance(source_extents, (list, tuple)) and len(source_extents) == 3:
            radius = max(float(record.get("radius") or 0.0), 0.0)
            return tuple(max(float(value) + radius * 2.0, 1e-6) for value in source_extents)
    if primitive_type == "dent_mask_set":
        centers = record.get("dent_centers")
        if isinstance(centers, (list, tuple)) and centers:
            try:
                coords = [
                    (float(point[0]), float(point[1]), float(point[2]))
                    for point in centers
                ]
                radius = max(float(record.get("radius") or 0.0), 0.0)
                mins = tuple(min(point[index] for point in coords) for index in range(3))
                maxs = tuple(max(point[index] for point in coords) for index in range(3))
                return tuple(max(maxs[index] - mins[index] + radius * 2.0, 1e-6) for index in range(3))
            except (TypeError, ValueError, IndexError):
                pass
    if primitive_type == "surface_patch_set":
        centers = record.get("patch_centers")
        if isinstance(centers, (list, tuple)) and centers:
            try:
                coords = [
                    (float(point[0]), float(point[1]), float(point[2]))
                    for point in centers
                ]
                length = max(float(record.get("length") or 1.0), 1e-6)
                width = max(float(record.get("width") or 1.0), 1e-6)
                height = max(float(record.get("depth") if record.get("depth") is not None else record.get("thickness") or 0.1), 1e-6)
                normal_axis = str(record.get("normal_axis") or record.get("axis") or "z")
                tangent_a, tangent_b = _tangent_axes(normal_axis)
                length_axis = str(record.get("length_axis") or tangent_a)
                width_axis = str(record.get("width_axis") or tangent_b)
                padding = [0.0, 0.0, 0.0]
                padding[_axis_index(length_axis)] = length
                padding[_axis_index(width_axis)] = width
                padding[_axis_index(normal_axis)] = height
                mins = tuple(min(point[index] for point in coords) for index in range(3))
                maxs = tuple(max(point[index] for point in coords) for index in range(3))
                return tuple(max(maxs[index] - mins[index] + padding[index], 1e-6) for index in range(3))
            except (TypeError, ValueError, IndexError):
                pass
    if primitive_type == "hinge":
        length = max(float(record.get("length") or 1.0), 1e-6)
        leaf_width = max(float(record.get("leaf_width") or record.get("width") or 0.5), 1e-6)
        leaf_thickness = max(float(record.get("leaf_thickness") or record.get("thickness") or 0.1), 1e-6)
        barrel_radius = max(float(record.get("barrel_radius") or record.get("radius") or 0.2), 1e-6)
        hinge_axis = str(record.get("hinge_axis") or record.get("axis") or "y")
        leaf_axis = str(record.get("leaf_axis") or record.get("width_axis") or "x")
        thickness_axes = [axis for axis in ("x", "y", "z") if axis not in {hinge_axis, leaf_axis}]
        thickness_axis = str(record.get("height_axis") or (thickness_axes[0] if thickness_axes else "z"))
        values = [barrel_radius * 2.0, barrel_radius * 2.0, barrel_radius * 2.0]
        values[_axis_index(hinge_axis)] = length
        values[_axis_index(leaf_axis)] = leaf_width * 2.0 + barrel_radius * 2.0
        values[_axis_index(thickness_axis)] = max(leaf_thickness, barrel_radius * 2.0)
        return (values[0], values[1], values[2])
    if primitive_type == "handle":
        span = max(float(record.get("span") or record.get("length") or 1.0), 1e-6)
        standoff = max(float(record.get("standoff") or record.get("height") or 0.5), 1e-6)
        grip_radius = max(float(record.get("grip_radius") or record.get("radius") or 0.1), 1e-6)
        pad_radius = max(float(record.get("pad_radius") or record.get("outer_radius") or grip_radius * 1.85), 1e-6)
        pad_thickness = max(float(record.get("pad_thickness") or record.get("thickness") or grip_radius * 0.42), 1e-6)
        span_axis = str(record.get("span_axis") or record.get("length_axis") or "x")
        normal_axis = str(record.get("normal_axis") or record.get("axis") or "z")
        cross_axes = [axis for axis in ("x", "y", "z") if axis not in {span_axis, normal_axis}]
        cross_axis = str(record.get("cross_axis") or record.get("width_axis") or (cross_axes[0] if cross_axes else "y"))
        values = [grip_radius * 2.0, grip_radius * 2.0, grip_radius * 2.0]
        values[_axis_index(span_axis)] = span + pad_radius * 2.0
        values[_axis_index(normal_axis)] = standoff + grip_radius
        values[_axis_index(cross_axis)] = max(pad_radius * 2.0, grip_radius * 2.0)
        values[_axis_index(normal_axis)] = max(values[_axis_index(normal_axis)], pad_thickness)
        return (values[0], values[1], values[2])
    if primitive_type == "flange" and record.get("outer_radius") is not None:
        radius = max(float(record["outer_radius"]), 1e-6)
        thickness = max(float(record.get("thickness") or radius * 0.25), 1e-6)
        axis = str(record.get("axis") or "z")
        values = [radius * 2.0, radius * 2.0, radius * 2.0]
        values[_axis_index(axis)] = thickness
        return (values[0], values[1], values[2])
    if primitive_type == "corner_guard_set":
        source_extents = record.get("source_extents")
        if isinstance(source_extents, (list, tuple)) and len(source_extents) == 3:
            thickness = max(float(record.get("thickness") or 0.0), 0.0)
            seat_depth = max(float(record.get("seat_depth") or 0.0), 0.0)
            outset = max(thickness - seat_depth, 0.0) * 2.0
            return tuple(max(float(value) + outset, 1e-6) for value in source_extents)
    if primitive_type == "revolved_profile":
        profile = record.get("profile_points")
        if isinstance(profile, (list, tuple)) and profile:
            try:
                axial = [float(point[0]) for point in profile]
                radial = [abs(float(point[1])) for point in profile]
            except (TypeError, ValueError, IndexError):
                pass
            else:
                axis = str(record.get("axis") or "y")
                diameter = max(radial, default=0.5) * 2.0
                values = [diameter, diameter, diameter]
                values[_axis_index(axis)] = max(max(axial) - min(axial), 1e-6)
                return (values[0], values[1], values[2])
    if primitive_type == "extruded_profile":
        profile_extents = _profile_2d_extents(record.get("profile_polygon"))
        height = record.get("extrude_height")
        if profile_extents is not None and height is not None:
            axis = str(record.get("axis") or "y")
            axial = max(float(height), 1e-6)
            u_extent = max(profile_extents[0], 1e-6)
            v_extent = max(profile_extents[1], 1e-6)
            if axis == "x":
                return (axial, v_extent, u_extent)
            if axis == "z":
                return (u_extent, v_extent, axial)
            return (u_extent, axial, v_extent)
    if primitive_type == "rounded_slot":
        length = max(float(record.get("length") or 1.0), 1e-6)
        width = max(float(record.get("width") or length), 1e-6)
        depth = max(float(record.get("depth") or width), 1e-6)
        axis = str(record.get("axis") or "z")
        values = [length, width, depth]
        if axis == "x":
            return (depth, length, width)
        if axis == "y":
            return (length, depth, width)
        return (values[0], values[1], values[2])
    if primitive_type == "countersunk_hole" and record.get("radius") is not None:
        radius = max(float(record["radius"]), 1e-6)
        depth = max(float(record.get("depth") or radius * 2.0), 1e-6)
        axis = str(record.get("axis") or "z")
        values = [radius * 2.0, radius * 2.0, radius * 2.0]
        values[_axis_index(axis)] = depth
        return (values[0], values[1], values[2])
    if primitive_type == "countersunk_hole_set" and record.get("radius") is not None:
        centers = record.get("hole_centers")
        if isinstance(centers, (list, tuple)) and centers:
            try:
                coords = [
                    (float(point[0]), float(point[1]), float(point[2]))
                    for point in centers
                ]
                radius = max(float(record["radius"]), 1e-6)
                depth = max(float(record.get("depth") or radius * 2.0), 1e-6)
                axis = str(record.get("axis") or "z")
                padding = [radius * 2.0, radius * 2.0, radius * 2.0]
                padding[_axis_index(axis)] = depth
                mins = tuple(min(point[index] for point in coords) for index in range(3))
                maxs = tuple(max(point[index] for point in coords) for index in range(3))
                return tuple(max(maxs[index] - mins[index] + padding[index], 1e-6) for index in range(3))
            except (TypeError, ValueError, IndexError):
                pass
    if primitive_type == "panel":
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        width_axis = str(record.get("width_axis") or tangent_a)
        height_axis = str(record.get("height_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(width_axis)] = width
        values[_axis_index(height_axis)] = height
        values[_axis_index(axis)] = thickness
        return (values[0], values[1], values[2])
    if primitive_type == "panel_frame":
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        axis = str(record.get("normal_axis") or record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        width_axis = str(record.get("width_axis") or tangent_a)
        height_axis = str(record.get("height_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(width_axis)] = width
        values[_axis_index(height_axis)] = height
        values[_axis_index(axis)] = thickness
        return (values[0], values[1], values[2])
    if primitive_type == "perforated_panel":
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        column_axis = str(record.get("column_axis") or tangent_a)
        row_axis = str(record.get("row_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(column_axis)] = width
        values[_axis_index(row_axis)] = height
        values[_axis_index(axis)] = thickness
        return (values[0], values[1], values[2])
    if primitive_type == "fastener_grid":
        rows = max(int(record.get("fastener_rows") or 1), 1)
        columns = max(int(record.get("fastener_columns") or 1), 1)
        spacing = max(float(record.get("fastener_spacing") or 1.0), 1e-6)
        radius = max(float(record.get("radius") or 0.1), 1e-6)
        washer_radius = max(float(record.get("washer_radius") or radius * 1.38), radius)
        washer_height = (
            max(float(record.get("washer_height") or 0.07), 0.0)
            if record.get("include_washer", True) is not False
            else 0.0
        )
        head_height = max(float(record.get("head_height") or record.get("height") or radius), 1e-6)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        column_axis = str(record.get("column_axis") or tangent_a)
        row_axis = str(record.get("row_axis") or tangent_b)
        outer_radius = max(radius, washer_radius)
        centers = record.get("fastener_centers")
        if isinstance(centers, (list, tuple)) and centers:
            try:
                coords = [
                    (float(point[0]), float(point[1]), float(point[2]))
                    for point in centers
                ]
                scales = record.get("fastener_scales")
                if isinstance(scales, (list, tuple)) and scales:
                    max_scale = max(max(float(value), 1e-6) for value in scales)
                else:
                    max_scale = 1.0
                mins = [min(point[index] for point in coords) for index in range(3)]
                maxs = [max(point[index] for point in coords) for index in range(3)]
                axis_index = _axis_index(axis)
                for index in range(3):
                    if index == axis_index:
                        mins[index] -= (washer_height + head_height) * max_scale
                        maxs[index] += (washer_height + head_height) * max_scale
                    else:
                        mins[index] -= outer_radius * max_scale
                        maxs[index] += outer_radius * max_scale
                return tuple(max(maxs[index] - mins[index], 1e-6) for index in range(3))
            except (TypeError, ValueError, IndexError):
                pass
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(column_axis)] = max(outer_radius * 2.0, (columns - 1) * spacing + outer_radius * 2.0)
        values[_axis_index(row_axis)] = max(outer_radius * 2.0, (rows - 1) * spacing + outer_radius * 2.0)
        values[_axis_index(axis)] = washer_height + head_height
        return (values[0], values[1], values[2])
    if primitive_type == "ribbed_panel":
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        rib_height = max(float(record.get("rib_height") or thickness * 0.65), 0.0)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        width_axis = str(record.get("width_axis") or tangent_a)
        height_axis = str(record.get("height_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(width_axis)] = width
        values[_axis_index(height_axis)] = height
        values[_axis_index(axis)] = thickness + rib_height
        return (values[0], values[1], values[2])
    if primitive_type == "structural_beam":
        length = max(float(record.get("length") or 1.0), 1e-6)
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        axis = str(record.get("axis") or "x")
        if axis == "x":
            return (length, width, height)
        if axis == "y":
            return (width, length, height)
        return (width, height, length)
    if primitive_type == "rail":
        length = max(float(record.get("length") or 1.0), 1e-6)
        profile = max(float(record.get("profile") or 1.0), 1e-6)
        profile_height = max(float(record.get("profile_height") or profile), 1e-6)
        axis = str(record.get("axis") or "x")
        if axis == "x":
            return (length, profile, profile_height)
        if axis == "y":
            return (profile, length, profile_height)
        return (profile, profile_height, length)
    if primitive_type == "louver_panel":
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        slat_depth = max(float(record.get("slat_depth") or thickness), 0.0)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        width_axis = str(record.get("width_axis") or tangent_a)
        height_axis = str(record.get("height_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(width_axis)] = width
        values[_axis_index(height_axis)] = height
        values[_axis_index(axis)] = thickness + slat_depth
        return (values[0], values[1], values[2])
    if primitive_type == "vent_slats":
        count = max(int(record.get("slat_count") or 1), 1)
        spacing = max(float(record.get("slat_spacing") or 1.0), 1e-6)
        length = max(float(record.get("length") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        length_axis = str(record.get("length_axis") or tangent_a)
        row_axis = str(record.get("row_axis") or tangent_b)
        centers = record.get("slat_centers")
        if isinstance(centers, (list, tuple)) and centers:
            try:
                coords = [
                    (float(point[0]), float(point[1]), float(point[2]))
                    for point in centers
                ]
                scales = record.get("slat_scales")
                if isinstance(scales, (list, tuple)) and scales:
                    max_scale = max(max(float(value), 1e-6) for value in scales)
                else:
                    max_scale = 1.0
                radius = max(length, height) * 0.5 * max_scale
                normal_half = thickness * 0.5 * max_scale
                mins = [min(point[index] for point in coords) for index in range(3)]
                maxs = [max(point[index] for point in coords) for index in range(3)]
                normal_index = _axis_index(axis)
                for index in range(3):
                    if index == normal_index:
                        mins[index] -= normal_half
                        maxs[index] += normal_half
                    else:
                        mins[index] -= radius
                        maxs[index] += radius
                return tuple(max(maxs[index] - mins[index], 1e-6) for index in range(3))
            except (TypeError, ValueError, IndexError):
                pass
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(length_axis)] = length
        values[_axis_index(row_axis)] = max(height, (count - 1) * spacing + height)
        values[_axis_index(axis)] = thickness
        return (values[0], values[1], values[2])
    if primitive_type == "ladder_frame":
        length = max(float(record.get("length") or 1.0), 1e-6)
        width = max(float(record.get("width") or 1.0), 1e-6)
        rail_radius = max(float(record.get("rail_radius") or 0.1), 1e-6)
        rung_radius = max(float(record.get("rung_radius") or rail_radius * 0.72), 1e-6)
        radius = max(rail_radius, rung_radius)
        length_axis = str(record.get("length_axis") or "y")
        width_axis = str(record.get("width_axis") or "x")
        remaining_axis = next(axis for axis in ("x", "y", "z") if axis not in {length_axis, width_axis})
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(length_axis)] = length + radius * 2.0
        values[_axis_index(width_axis)] = width + radius * 2.0
        values[_axis_index(remaining_axis)] = radius * 2.0
        return (values[0], values[1], values[2])
    if primitive_type == "truss_frame":
        length = max(float(record.get("length") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        member_radius = max(float(record.get("member_radius") or 0.1), 1e-6)
        depth = max(float(record.get("depth") or member_radius * 2.0), 0.0)
        length_axis = str(record.get("length_axis") or "y")
        height_axis = str(record.get("height_axis") or "z")
        depth_axis = str(record.get("depth_axis") or "x")
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(length_axis)] = length + member_radius * 2.0
        values[_axis_index(height_axis)] = height + member_radius * 2.0
        values[_axis_index(depth_axis)] = max(depth, member_radius * 2.0) + member_radius * 2.0
        return (values[0], values[1], values[2])
    if primitive_type == "support_bracket":
        width = max(float(record.get("width") or 1.0), 1e-6)
        height = max(float(record.get("height") or 1.0), 1e-6)
        depth = max(float(record.get("depth") or 1.0), 1e-6)
        normal_axis = str(record.get("normal_axis") or record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(normal_axis)
        width_axis = str(record.get("width_axis") or tangent_a)
        height_axis = str(record.get("height_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(width_axis)] = width
        values[_axis_index(height_axis)] = height
        values[_axis_index(normal_axis)] = depth
        return (values[0], values[1], values[2])
    if primitive_type == "trim_band":
        length = max(float(record.get("length") or 1.0), 1e-6)
        width = max(float(record.get("width") or 1.0), 1e-6)
        thickness = max(float(record.get("thickness") or 0.1), 1e-6)
        axis = str(record.get("axis") or "z")
        tangent_a, tangent_b = _tangent_axes(axis)
        length_axis = str(record.get("length_axis") or tangent_a)
        width_axis = str(record.get("width_axis") or tangent_b)
        values = [1e-6, 1e-6, 1e-6]
        values[_axis_index(length_axis)] = length
        values[_axis_index(width_axis)] = width
        values[_axis_index(axis)] = thickness
        return (values[0], values[1], values[2])
    if primitive_type == "swept_profile":
        path = record.get("sweep_path")
        cross_section = _profile_2d_extents(record.get("cross_section"))
        if isinstance(path, (list, tuple)) and path:
            try:
                xs = [float(point[0]) for point in path]
                ys = [float(point[1]) for point in path]
                zs = [float(point[2]) for point in path]
            except (TypeError, ValueError, IndexError):
                pass
            else:
                reach = max(cross_section or (1.0, 1.0)) * 0.5
                return (
                    max(max(xs) - min(xs) + reach * 2.0, 1e-6),
                    max(max(ys) - min(ys) + reach * 2.0, 1e-6),
                    max(max(zs) - min(zs) + reach * 2.0, 1e-6),
                )
    if primitive_type == "curved_tube":
        if (
            record.get("radius") is not None
            and record.get("tube_radius") is not None
            and record.get("angle_degrees") is not None
        ):
            radius = float(record["radius"])
            tube_radius = float(record["tube_radius"])
            angle_degrees = float(record["angle_degrees"])
            path_segments = int(record.get("path_segments") or max(8, math.ceil(abs(angle_degrees) / 10.0)))
            path = _curved_tube_path(
                plane_axis=str(record.get("plane_axis") or "z"),
                radius=radius,
                angle_degrees=angle_degrees,
                start_angle_degrees=float(record.get("start_angle_degrees") or 0.0),
                path_segments=max(3, min(path_segments, 512)),
            )
            xs = [point[0] for point in path]
            ys = [point[1] for point in path]
            zs = [point[2] for point in path]
            return (
                max(max(xs) - min(xs) + tube_radius * 2.0, 1e-6),
                max(max(ys) - min(ys) + tube_radius * 2.0, 1e-6),
                max(max(zs) - min(zs) + tube_radius * 2.0, 1e-6),
            )
    if primitive_type == "torus" and record.get("major_radius") is not None and record.get("minor_radius") is not None:
        radius = (float(record["major_radius"]) + float(record["minor_radius"])) * 2.0
        return (max(radius, 1e-6), max(radius, 1e-6), max(radius, 1e-6))

    return (1.0, 1.0, 1.0)


def _record_bounds(record: _V1Record) -> tuple[tuple[float, float, float], tuple[float, float, float]]:
    mesh_bounds = _record_mesh_vertex_bounds(record)
    if mesh_bounds is not None:
        return mesh_bounds
    if str(record.get("primitive_type") or "") == "component_assembly":
        assembly_bounds = _component_assembly_record_bounds(record)
        if assembly_bounds is not None:
            return assembly_bounds

    center = _record_center_tuple(record)
    extents = _record_context_extents(record)
    half = tuple(value * 0.5 for value in extents)
    return (
        (center[0] - half[0], center[1] - half[1], center[2] - half[2]),
        (center[0] + half[0], center[1] + half[1], center[2] + half[2]),
    )


def _context_child_records(record: _V1Record) -> tuple[_V1Record, ...]:
    children = record.get("v2_context_records")
    if isinstance(children, (list, tuple)) and children:
        out: list[_V1Record] = []
        for child in children:
            if isinstance(child, dict) and child.get("primitive_type"):
                out.extend(_context_child_records(dict(child)))
        if out:
            return tuple(out)
    return (dict(record),)


def _context_records_for_aggregate(records: tuple[_V1Record, ...]) -> tuple[_V1Record, ...]:
    out: list[_V1Record] = []
    seen: set[str] = set()
    for record in records:
        for child in _context_child_records(record):
            part = str(child.get("part") or "")
            primitive_type = str(child.get("primitive_type") or "")
            center = tuple(child.get("center") or ())
            key = repr((part, primitive_type, center, child.get("blend_mode", "union")))
            if key in seen:
                continue
            seen.add(key)
            out.append(dict(child))
    return tuple(out)


def _aggregate_context_record(root: str, records: tuple[_V1Record, ...]) -> _V1Record:
    context_records = _context_records_for_aggregate(records)
    bounds = [_record_bounds(record) for record in context_records]
    mins = tuple(min(pair[0][axis] for pair in bounds) for axis in range(3))
    maxs = tuple(max(pair[1][axis] for pair in bounds) for axis in range(3))
    center = tuple((mins[axis] + maxs[axis]) * 0.5 for axis in range(3))
    extents = tuple(max(maxs[axis] - mins[axis], 1e-6) for axis in range(3))
    parts: list[str] = []
    for record in context_records:
        for part in record.get("v2_context_parts", [record.get("part")]):
            text = str(part or "").strip()
            if text and text not in parts:
                parts.append(text)
    return {
        "primitive_type": "box",
        "part": root,
        "center": center,
        "extents": extents,
        "tags": ["source_context_aggregate", f"source_context_root_{root}"],
        "blend_mode": "union",
        "rounding": 0.0,
        "v2_op": "source_context.aggregate",
        "v2_context_aggregate": True,
        "v2_context_parts": parts,
        "v2_context_record_count": len(context_records),
        "v2_context_primitive_types": sorted(
            {str(record.get("primitive_type") or "") for record in context_records if record.get("primitive_type")}
        ),
        # ``context_records`` already contains fresh top-level dicts
        # produced by ``_context_records_for_aggregate``; storing those
        # directly avoids exponential deepcopy blowup when an existing
        # aggregate is re-merged with a new record (every prior merge
        # would otherwise deep-clone the entire aggregate history).
        "v2_context_records": list(context_records),
    }


def _kernel_record_for_context_aggregate(
    record: _V1Record,
    *,
    geometry_kernel: Any,
) -> _V1Record:
    context_records = _context_records_for_aggregate(_context_child_records(record))
    if not context_records:
        raise ValueError("context aggregate has no source records")
    if len(context_records) == 1:
        return dict(context_records[0])

    from ..geometry.shape_ir_lowering import execute_shape_ir_kernel_program

    result = execute_shape_ir_kernel_program(
        geometry_kernel,
        _shape_ir_for_kernel_records(
            context_records,
            asset_name="shape_ir_v2_context_aggregate_source",
            blueprint_id="shape_ir_v2_context_aggregate_source",
        ),
        program_kind="boolean",
        route="shape_ir_v2_context_aggregate",
        backend=getattr(geometry_kernel, "name", None),
    )
    parts = [
        str(part)
        for part in record.get("v2_context_parts", [])
        if str(part or "").strip()
    ]
    if not parts:
        parts = [
            str(child.get("part"))
            for child in context_records
            if str(child.get("part") or "").strip()
        ]
    context_op = ShapeOp(
        op="source_context.aggregate",
        target=str(record.get("part") or "context_aggregate"),
        parameters={},
    )
    output_record = _kernel_mesh_record_for_result(
        context_op,
        result=result,
        part=str(record.get("part") or "context_aggregate"),
        tags=[
            *[str(tag) for tag in record.get("tags", []) if str(tag)],
            "source_context_kernel_aggregate",
        ],
        blend_mode=str(record.get("blend_mode") or "union"),
        modifier_name="v2_context_aggregate_modifier",
        modifier_payload={
            "source_record_count": len(context_records),
            "kernel_boolean_method": f"context_aggregate_boolean_{_op_tag_token(context_op.op)}_v1",
            **_source_record_provenance_payload(context_records),
        },
        geometry_kernel=geometry_kernel,
        boolean_seam_groups=_record_group_list(context_records, "boolean_seam_groups"),
        bevel_seam_groups=_record_group_list(context_records, "bevel_seam_groups"),
        hard_edge_groups=_record_group_list(context_records, "hard_edge_groups"),
        source_records=context_records,
        result_primitive_type="boolean_mesh",
    )
    output_record["v2_context_aggregate"] = True
    output_record["v2_context_parts"] = parts
    output_record["v2_context_record_count"] = len(context_records)
    output_record["v2_context_primitive_types"] = _dedupe_text_values(
        [record.get("primitive_type") for record in context_records]
    )
    output_record["v2_context_records"] = [
        deepcopy(context_record) for context_record in context_records
    ]
    metadata = output_record.get("semantic_metadata")
    metadata = dict(metadata) if isinstance(metadata, dict) else {}
    v2_metadata = metadata.get(_V2_PROVENANCE_METADATA_KEY)
    v2_metadata = dict(v2_metadata) if isinstance(v2_metadata, dict) else {}
    v2_metadata["context_record_count"] = len(context_records)
    v2_metadata["context_parts"] = parts
    v2_metadata["context_primitive_types"] = list(output_record["v2_context_primitive_types"])
    metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    output_record["semantic_metadata"] = metadata
    return output_record


def _merge_context_record(root: str, existing: _V1Record | None, record: _V1Record) -> _V1Record:
    if existing is None:
        return _aggregate_context_record(root, (record,))
    return _aggregate_context_record(root, (existing, record))


def _record_should_merge_into_root_context(record: _V1Record) -> bool:
    tags = {str(tag) for tag in record.get("tags") or []}
    if "surface_detail" in tags or "material_zone" in tags:
        return False
    component = str(record.get("component") or "")
    if component in {
        "trim_band",
        "fastener_stack_array",
        "vent_slat_array",
        "panel_frame",
        "corner_guard",
        "socket",
        "socket_clearance",
        "bracket",
        "support_bracket",
        "mount_plate",
        "weld_seam",
    }:
        return False
    return True


_TARGET_SURFACE_FACE_KEYS = ("target_face", "surface_face", "face_selector")

_TARGET_SURFACE_FACE_ALIASES: dict[str, tuple[str, float, tuple[str, str]]] = {
    "front": ("z", 1.0, ("y", "x")),
    "front_face": ("z", 1.0, ("y", "x")),
    "positive_z": ("z", 1.0, ("y", "x")),
    "pos_z": ("z", 1.0, ("y", "x")),
    "+z": ("z", 1.0, ("y", "x")),
    "back": ("z", -1.0, ("y", "x")),
    "back_face": ("z", -1.0, ("y", "x")),
    "rear": ("z", -1.0, ("y", "x")),
    "negative_z": ("z", -1.0, ("y", "x")),
    "neg_z": ("z", -1.0, ("y", "x")),
    "-z": ("z", -1.0, ("y", "x")),
    "top": ("y", 1.0, ("z", "x")),
    "top_face": ("y", 1.0, ("z", "x")),
    "upper": ("y", 1.0, ("z", "x")),
    "positive_y": ("y", 1.0, ("z", "x")),
    "pos_y": ("y", 1.0, ("z", "x")),
    "+y": ("y", 1.0, ("z", "x")),
    "bottom": ("y", -1.0, ("z", "x")),
    "bottom_face": ("y", -1.0, ("z", "x")),
    "lower": ("y", -1.0, ("z", "x")),
    "negative_y": ("y", -1.0, ("z", "x")),
    "neg_y": ("y", -1.0, ("z", "x")),
    "-y": ("y", -1.0, ("z", "x")),
    "right": ("x", 1.0, ("y", "z")),
    "right_face": ("x", 1.0, ("y", "z")),
    "positive_x": ("x", 1.0, ("y", "z")),
    "pos_x": ("x", 1.0, ("y", "z")),
    "+x": ("x", 1.0, ("y", "z")),
    "left": ("x", -1.0, ("y", "z")),
    "left_face": ("x", -1.0, ("y", "z")),
    "negative_x": ("x", -1.0, ("y", "z")),
    "neg_x": ("x", -1.0, ("y", "z")),
    "-x": ("x", -1.0, ("y", "z")),
}


def _target_surface_face_spec(
    parameters: dict[str, Any],
    *,
    operation_name: str,
) -> tuple[str, str, str, float, tuple[str, str]] | None:
    for key in _TARGET_SURFACE_FACE_KEYS:
        if key not in parameters:
            continue
        raw_value = str(parameters.get(key) or "").strip().lower()
        if not raw_value:
            continue
        token = raw_value.replace(" ", "_").replace("-", "_")
        token = token.replace("positive_", "pos_").replace("negative_", "neg_")
        if token in _TARGET_SURFACE_FACE_ALIASES:
            axis, sign, tangent_axes = _TARGET_SURFACE_FACE_ALIASES[token]
            return key, token, axis, sign, tangent_axes
        raise ValueError(
            f"parameter '{key}' for {operation_name} must be one of: "
            "front, back, top, bottom, left, right, +x, -x, +y, -y, +z, -z"
        )
    return None


def _target_surface_normal_axis(
    parameters: dict[str, Any],
    default_axis: str,
    *,
    axis_key: str,
    operation_name: str,
) -> str:
    face_spec = _target_surface_face_spec(parameters, operation_name=operation_name)
    explicit_axis = ""
    if axis_key in parameters:
        explicit_axis = str(parameters.get(axis_key) or "").strip().lower()
        if explicit_axis not in {"x", "y", "z"}:
            raise ValueError(f"parameter '{axis_key}' must be one of: x, y, z")
    if face_spec is not None:
        face_axis = face_spec[2]
        if explicit_axis and explicit_axis != face_axis:
            raise ValueError(f"parameter '{axis_key}' conflicts with {operation_name} target_face")
        return face_axis
    return default_axis


def _target_surface_normal_sign(
    parameters: dict[str, Any],
    *,
    operation_name: str,
) -> float:
    face_spec = _target_surface_face_spec(parameters, operation_name=operation_name)
    face_sign = face_spec[3] if face_spec is not None else None
    if "normal_sign" in parameters:
        explicit_sign = -1.0 if _optional_float_param(parameters, "normal_sign", 1.0) < 0.0 else 1.0
        if face_sign is not None and explicit_sign != face_sign:
            raise ValueError(f"parameter 'normal_sign' conflicts with {operation_name} target_face")
        return explicit_sign
    if "side" in parameters:
        explicit_side = _optional_string_param(parameters, "side", "positive", allowed={"positive", "negative"})
        explicit_sign = 1.0 if explicit_side == "positive" else -1.0
        if face_sign is not None and explicit_sign != face_sign:
            raise ValueError(f"parameter 'side' conflicts with {operation_name} target_face")
        return explicit_sign
    if face_sign is not None:
        return face_sign
    return 1.0


def _target_surface_tangent_axes(
    parameters: dict[str, Any],
    default_axes: tuple[str, str],
    *,
    operation_name: str,
) -> tuple[str, str]:
    face_spec = _target_surface_face_spec(parameters, operation_name=operation_name)
    if face_spec is not None:
        return face_spec[4]
    return default_axes


def _target_surface_placement(
    parameters: dict[str, Any],
    source_record: _V1Record,
    *,
    normal_axis: str,
    thickness_cm: float,
    blend_mode: str,
    subtract_depth_cm: float | None = None,
    default_seat_depth_cm: float = 0.0,
    tangent_axes: tuple[str, ...] = (),
) -> tuple[tuple[float, float, float], dict[str, Any]]:
    source_center = _record_placement_center(source_record)
    source_normal_extent = _record_extent_along_axis(source_record, normal_axis)
    face_spec = _target_surface_face_spec(parameters, operation_name="target surface placement")
    normal_sign = _target_surface_normal_sign(parameters, operation_name="target surface placement")
    seat_depth = _optional_float_param(parameters, "seat_depth_cm", default_seat_depth_cm)
    if seat_depth < 0.0:
        raise ValueError("parameter 'seat_depth_cm' must be >= 0")
    if blend_mode in {"subtract", "intersect"}:
        cutter_depth = float(subtract_depth_cm if subtract_depth_cm is not None else thickness_cm)
        normal_offset = source_normal_extent * 0.5 - cutter_depth * 0.5 - seat_depth
    else:
        normal_offset = source_normal_extent * 0.5 + float(thickness_cm) * 0.5 - seat_depth
    metadata = {
        "placement": "target_surface_context_v1",
        "target_source_part": str(source_record.get("part") or ""),
        "target_source_primitive_type": str(source_record.get("primitive_type") or ""),
        "target_source_normal_extent_cm": source_normal_extent,
        "normal_axis": normal_axis,
        "normal_sign": normal_sign,
        "seat_depth_cm": seat_depth,
        **_source_context_operation_payload(
            source_record,
            metadata_key="v2_target_surface_context",
        ),
        **(
            {
                "target_face": face_spec[1],
                "target_face_source_parameter": face_spec[0],
            }
            if face_spec is not None
            else {}
        ),
    }
    for axis in tangent_axes:
        metadata[f"target_source_{axis}_extent_cm"] = _record_extent_along_axis(source_record, axis)
    tangent_offset, tangent_offset_metadata = _surface_tangent_offset(parameters, tangent_axes)
    if tangent_offset_metadata:
        metadata.update(tangent_offset_metadata)
    return (
        _add_points(
            _add_points(source_center, _axis_center_shift(normal_axis, normal_sign * normal_offset)),
            tangent_offset,
        ),
        metadata,
    )


def _source_context_target_surface_records(
    source_record: _V1Record | None,
    *,
    context_tag: str,
) -> tuple[_V1Record, ...]:
    if source_record is None:
        return ()
    if not (
        source_record.get("v2_context_aggregate")
        or source_record.get("v2_context_records")
    ):
        return (source_record,)
    return _context_expanded_kernel_source_records(
        (source_record,),
        context_tag=context_tag,
        metadata_key="v2_target_surface_context",
    )


def _use_aggregate_target_surface(parameters: Mapping[str, Any]) -> bool:
    scope = str(
        parameters.get("target_surface_scope")
        or parameters.get("source_context_scope")
        or ""
    ).strip().lower()
    return scope in {"aggregate", "logical_aggregate", "single_aggregate"}


def _lower_source_context_target_surface_children(
    op: ShapeOp,
    *,
    source_records: tuple[_V1Record, ...],
    lowerer: Any,
    geometry_kernel: Any | None,
) -> tuple[_V1Record, ...]:
    records: list[_V1Record] = []
    for child_index, source_record in enumerate(source_records):
        child_op = _context_child_source_op(
            op,
            source_record=source_record,
            child_index=child_index,
            child_count=len(source_records),
        )
        records.extend(
            _normalize_lowering(
                lowerer(
                    child_op,
                    geometry_kernel=geometry_kernel,
                )
            )
        )
    return tuple(records)


def _surface_tangent_offset(
    parameters: dict[str, Any],
    tangent_axes: tuple[str, ...],
) -> tuple[tuple[float, float, float], dict[str, Any]]:
    offsets = [0.0, 0.0, 0.0]
    values_by_axis: dict[str, float] = {}
    raw_pair = parameters.get("surface_offset_cm")
    if isinstance(raw_pair, (list, tuple)) and len(raw_pair) >= 2:
        for index, axis in enumerate(tangent_axes[:2]):
            value = float(raw_pair[index])
            offsets[_axis_index(axis)] += value
            values_by_axis[axis] = values_by_axis.get(axis, 0.0) + value
    for index, axis in enumerate(tangent_axes):
        candidate_keys = [
            f"surface_{axis}_offset_cm",
            f"{axis}_offset_cm",
        ]
        if index == 0:
            candidate_keys.extend(("u_offset_cm", "column_offset_cm"))
        elif index == 1:
            candidate_keys.extend(("v_offset_cm", "row_offset_cm"))
        for key in candidate_keys:
            if key not in parameters:
                continue
            value = _float_param(parameters, key)
            offsets[_axis_index(axis)] += value
            values_by_axis[axis] = values_by_axis.get(axis, 0.0) + value
            break
    if not values_by_axis:
        return (0.0, 0.0, 0.0), {}
    return (
        (offsets[0], offsets[1], offsets[2]),
        {
            "surface_offset_axes": list(tangent_axes),
            "surface_offset_cm": {
                axis: float(values_by_axis.get(axis, 0.0))
                for axis in tangent_axes
                if axis in values_by_axis
            },
        },
    )


def _register_source_context(record: _V1Record, source_context: dict[str, _V1Record]) -> None:
    if str(record.get("blend_mode") or "union") != "union":
        return
    if not record.get("primitive_type"):
        return
    part = str(record.get("part") or "").strip()
    if not part:
        return
    source_context.setdefault(part, dict(record))
    root = part.split(".", 1)[0]
    if root and root != part and _record_should_merge_into_root_context(record):
        source_context[root] = _merge_context_record(root, source_context.get(root), record)


def _register_source_context_alias(
    record: _V1Record,
    source_context: dict[str, _V1Record],
    *,
    key: str | None,
) -> None:
    alias = str(key or "").strip()
    if not alias:
        return
    if str(record.get("blend_mode") or "union") != "union":
        return
    if not record.get("primitive_type"):
        return
    source_context.setdefault(alias, dict(record))
    root = alias.split(".", 1)[0]
    if root and root != alias and _record_should_merge_into_root_context(record):
        source_context[root] = _merge_context_record(root, source_context.get(root), record)


def _with_contextual_source(op: ShapeOp, source_context: dict[str, _V1Record]) -> ShapeOp:
    if op.op not in _CONTEXTUAL_SOURCE_OPS:
        return op
    normalized_parameters = _normalized_operation_parameters(op)
    if normalized_parameters != op.parameters:
        op = ShapeOp(
            op=op.op,
            target=op.target,
            parameters=normalized_parameters,
            purpose=op.purpose,
        )
    source_value = op.parameters.get("source")
    if isinstance(source_value, str):
        source_key = source_value.strip()
        if source_key:
            source = source_context.get(source_key)
            if source is not None:
                parameters = dict(op.parameters)
                parameters["source"] = dict(source)
                parameters.setdefault("source_context_key", source_key)
                source_context_keys = [source_key]
                for contextual_key in ("structuring", "structuring_source", "kernel"):
                    if contextual_key not in parameters:
                        continue
                    structuring_key = str(parameters.get(contextual_key) or "").strip()
                    if not structuring_key:
                        continue
                    structuring = source_context.get(structuring_key)
                    if structuring is None:
                        continue
                    parameters[contextual_key] = dict(structuring)
                    if structuring_key not in source_context_keys:
                        source_context_keys.append(structuring_key)
                parameters.setdefault("source_context_keys", source_context_keys)
                return ShapeOp(
                    op=op.op,
                    target=op.target,
                    parameters=parameters,
                    purpose=op.purpose,
                )
    if "sources" in op.parameters:
        raw_sources = op.parameters.get("sources")
        if not isinstance(raw_sources, (list, tuple)):
            return op
        resolved_sources: list[Any] = []
        source_keys: list[str] = []
        changed = False
        for source in raw_sources:
            if isinstance(source, str):
                source_key = source.strip()
                context_source = source_context.get(source_key)
                if context_source is None:
                    resolved_sources.append(source)
                    continue
                resolved_sources.append(dict(context_source))
                source_keys.append(source_key)
                changed = True
            else:
                resolved_sources.append(source)
        if not changed:
            return op
        parameters = dict(op.parameters)
        parameters["sources"] = resolved_sources
        parameters.setdefault("source_context_keys", source_keys)
        if source_keys:
            parameters.setdefault("source_context_key", source_keys[0])
        return ShapeOp(op=op.op, target=op.target, parameters=parameters, purpose=op.purpose)
    for contextual_key in ("structuring", "structuring_source", "kernel"):
        if contextual_key not in op.parameters:
            continue
        source_key = str(op.parameters.get(contextual_key) or "").strip()
        if not source_key:
            continue
        source = source_context.get(source_key)
        if source is None:
            continue
        parameters = dict(op.parameters)
        parameters[contextual_key] = dict(source)
        parameters.setdefault("source_context_key", source_key)
        parameters.setdefault("source_context_keys", [source_key])
        return ShapeOp(op=op.op, target=op.target, parameters=parameters, purpose=op.purpose)
    for key in _target_source_keys(op.target):
        source = source_context.get(key)
        if source is None:
            continue
        parameters = dict(op.parameters)
        parameters["source"] = dict(source)
        parameters.setdefault("source_context_key", key)
        return ShapeOp(op=op.op, target=op.target, parameters=parameters, purpose=op.purpose)
    return op


def _with_contextual_target(op: ShapeOp, source_context: dict[str, _V1Record]) -> ShapeOp:
    if op.op not in _CONTEXTUAL_TARGET_OPS:
        return op
    normalized_parameters = _normalized_operation_parameters(op)
    if normalized_parameters != op.parameters:
        op = ShapeOp(
            op=op.op,
            target=op.target,
            parameters=normalized_parameters,
            purpose=op.purpose,
        )
    for parameter_key in ("target", "target_surface", "surface", "onto"):
        if parameter_key not in op.parameters:
            continue
        target_value = op.parameters.get(parameter_key)
        if not isinstance(target_value, str):
            return op
        target_key = str(target_value or "").strip()
        if not target_key:
            return op
        target = source_context.get(target_key)
        if target is None:
            return op
        parameters = dict(op.parameters)
        parameters[parameter_key] = dict(target)
        parameters.setdefault("target_context_key", target_key)
        parameters.setdefault("target_context_parameter", parameter_key)
        return ShapeOp(op=op.op, target=op.target, parameters=parameters, purpose=op.purpose)
    for key in _target_source_keys(op.target):
        target = source_context.get(key)
        if target is None:
            continue
        parameters = dict(op.parameters)
        parameters["target"] = dict(target)
        parameters.setdefault("target_context_key", key)
        return ShapeOp(op=op.op, target=op.target, parameters=parameters, purpose=op.purpose)
    return op


def _record_matches_source_context_key(record: _V1Record, key: str) -> bool:
    part = str(record.get("part") or "").strip()
    if part == key:
        return True
    context_parts = record.get("v2_context_parts")
    if isinstance(context_parts, (list, tuple)) and key in {str(part) for part in context_parts}:
        return True
    if "." not in key and part.startswith(f"{key}."):
        return True
    return False


def _record_should_be_removed_for_context_replacement(record: _V1Record, key: str) -> bool:
    if not _record_matches_source_context_key(record, key):
        return False
    part = str(record.get("part") or "").strip()
    if part == key:
        return True
    if "." not in key and part.startswith(f"{key}."):
        return _record_should_merge_into_root_context(record)
    context_parts = record.get("v2_context_parts")
    if isinstance(context_parts, (list, tuple)) and key in {str(part) for part in context_parts}:
        return _record_should_merge_into_root_context(record)
    return True


def _replace_contextual_source_records(
    records: list[_V1Record],
    source_context: dict[str, _V1Record],
    *,
    key: str,
) -> tuple[str, ...]:
    replaced_aliases: list[str] = []
    records[:] = [
        record
        for record in records
        if not _record_should_be_removed_for_context_replacement(record, key)
    ]
    for context_key in list(source_context):
        if context_key == key or ("." not in key and context_key.startswith(f"{key}.")):
            replaced_aliases.append(context_key)
            del source_context[context_key]
    return tuple(replaced_aliases)


def _should_replace_contextual_source_records(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None,
) -> bool:
    if op.op not in _SOURCE_REPLACEMENT_OPS:
        return False
    if geometry_kernel is None and op.op in _PRESERVE_CONTEXTUAL_SOURCE_WITHOUT_KERNEL_OPS:
        return False
    return True


def _v1_record_for_solid_box(op: ShapeOp) -> dict[str, Any]:
    """Lower a ``solid.box`` op to a v1-compatible record."""
    parameters = _normalized_operation_parameters(op)
    width = _float_param(parameters, "width_cm")
    height = _float_param(parameters, "height_cm")
    depth = _float_param(parameters, "depth_cm")
