def _v1_record_for_solid_curve_lofted_solid(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None = None,
) -> dict[str, Any]:
    """Lower curve-backed loft sections to the stable lofted_solid primitive."""
    parameters = op.parameters
    sections_value = parameters["sections"]
    if not isinstance(sections_value, (list, tuple)):
        raise ValueError("parameter 'sections' must be a sequence of section records")
    if len(sections_value) < 2:  # noqa: PLR2004
        raise ValueError("parameter 'sections' must contain at least 2 sections")

    profile_point_count = _curve_int_value(
        parameters,
        ("section_samples", "profile_samples", "samples", "sample_count"),
        default=48,
        minimum=3,
        maximum=2048,
    )
    cross_sections: list[tuple[tuple[float, float], ...]] = []
    section_centers: list[tuple[float, float, float]] = []
    section_metadata: list[dict[str, Any]] = []
    path_centers_result = _loft_section_centers_from_parameters(
        parameters,
        count=len(sections_value),
        section_label="solid.curve_lofted_solid sections",
    )
    path_centers: tuple[tuple[float, float, float], ...] | None = None
    path_center_metadata: dict[str, Any] = {}
    if path_centers_result is not None:
        path_centers, path_center_metadata = path_centers_result
    for index, raw_section in enumerate(sections_value):
        if not isinstance(raw_section, dict):
            raise ValueError(f"parameter 'sections' item {index} must be a dict")
        curve_key, curve_payload = _curve_loft_section_curve_payload(
            raw_section,
            index=index,
        )
        polygon, curve_metadata = _sample_closed_curve_polygon_payload(
            curve_payload,
            key=f"sections[{index}].{curve_key}",
            default_samples=profile_point_count,
        )
        resampled_polygon = _resample_closed_polygon(
            polygon,
            count=profile_point_count,
            key=f"sections[{index}].{curve_key}",
        )
        scale = _curve_loft_section_scale(raw_section, index=index)
        offset = _curve_loft_section_offset(raw_section, index=index)
        twist_degrees = _curve_loft_section_twist_degrees(raw_section)
        cross_sections.append(
            _transform_curve_loft_polygon(
                resampled_polygon,
                scale=scale,
                offset=offset,
                twist_degrees=twist_degrees,
            )
        )

        center = raw_section.get("center")
        if center is None:
            if path_centers is None:
                raise ValueError(
                    f"parameter 'sections' item {index} requires 'center' "
                    "unless section_centers, section_path, or section_path_curve is provided"
                )
            section_center = path_centers[index]
            center_source_kind = str(
                path_center_metadata.get("section_center_source_kind")
                or "sampled_section_path_curve"
            )
            center_source_parameter = str(
                path_center_metadata.get("section_center_source_parameter") or ""
            )
        else:
            section_center = _point_list_param(
                {"center": [center]},
                "center",
                dimensions=3,
                min_points=1,
            )[0]
            center_source_kind = "explicit_section_center"
            center_source_parameter = f"sections[{index}].center"
        section_centers.append(section_center)
        section_metadata.append(
            {
                "index": index,
                "curve_key": curve_key,
                "input_point_count": curve_metadata.get("input_point_count"),
                "curve_kind": curve_metadata.get("curve_kind"),
                "rational": curve_metadata.get("rational"),
                "degree": curve_metadata.get("degree"),
                "sampled_point_count": curve_metadata.get("sampled_point_count"),
                "resampled_point_count": profile_point_count,
                "scale": scale,
                "offset": offset,
                "twist_degrees": twist_degrees,
                "center": section_center,
                "center_source_kind": center_source_kind,
                "center_source_parameter": center_source_parameter,
            }
        )

    modifier = {
        "method": "sampled_curve_lofted_solid_v1",
        "target_primitive": "lofted_solid",
        "section_count": len(section_centers),
        "profile_point_count": profile_point_count,
        "section_curve_metadata": section_metadata,
        **path_center_metadata,
    }
    record = {
        "primitive_type": "lofted_solid",
        "part": op.target or "curve_lofted_solid",
        "center": _center_param(parameters),
        "cross_sections": tuple(cross_sections),
        "section_centers": tuple(section_centers),
        "tags": ["solid_curve_lofted_solid", "curve_profile", "curve_loft"],
        "blend_mode": _optional_blend_mode(parameters),
        "rounding": 0.0,
        "v2_op": op.op,
        "v2_purpose": op.purpose,
        "v2_curve_loft_modifier": modifier,
    }
    record = _attach_direct_polybevel_modifier(
        record,
        parameters,
        source_operation=op.op,
        target_primitive="lofted_solid",
    )
    if geometry_kernel is not None:
        return _kernel_profile_record_for_single_source(
            op,
            source_record=record,
            geometry_kernel=geometry_kernel,
            route="shape_ir_v2_solid_curve_lofted_solid",
            asset_name="shape_ir_v2_solid_curve_lofted_solid_source",
            blueprint_id="shape_ir_v2_solid_curve_lofted_solid_source",
            modifier_name="v2_curve_loft_modifier",
            modifier_payload=modifier,
            kernel_tag="curve_lofted_solid_kernel_program",
            profile_kind="curve_lofted_solid",
        )
    return record


def _v1_record_for_solid_swept_profile(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None = None,
) -> dict[str, Any]:
    """Lower a ``solid.swept_profile`` op to a v1 swept profile."""
    parameters = op.parameters
    cross_section_metadata: dict[str, Any] | None = None
    sweep_metadata: dict[str, Any] | None = None
    cross_section_key = "cross_section"
    if "cross_section" in parameters:
        cross_section = _point_list_param(
            parameters,
            "cross_section",
            dimensions=2,
            min_points=3,
        )
    else:
        for candidate_key in ("cross_section_curve", "profile_curve", "curve"):
            if candidate_key in parameters:
                cross_section_key = candidate_key
                break
        if cross_section_key == "cross_section":
            raise ValueError("solid.swept_profile requires cross_section or cross_section_curve")
        cross_section, cross_section_metadata = _sample_curve_profile_param(
            parameters,
            cross_section_key,
            dimensions=2,
            min_points=3,
            close_polygon=True,
        )
    path_key = "sweep_path" if "sweep_path" in parameters else ("path" if "path" in parameters else "")
    if path_key:
        sweep_path = _point_list_param(
            parameters,
            path_key,
            dimensions=3,
            min_points=2,
        )
    else:
        for candidate_key in ("sweep_curve", "path_curve"):
            if candidate_key in parameters:
                path_key = candidate_key
                break
        if not path_key:
            raise ValueError("solid.swept_profile requires sweep_path, path, or sweep_curve")
        sweep_path, sweep_metadata = _sample_curve_profile_param(
            parameters,
            path_key,
            dimensions=3,
            min_points=2,
            close_polygon=False,
        )
    record = {
        "primitive_type": "swept_profile",
        "part": op.target or "body",
        "center": _center_param(parameters),
        "cross_section": cross_section,
        "sweep_path": sweep_path,
        "tags": [],
        "blend_mode": "union",
        "rounding": 0.0,
        "v2_op": op.op,
        "v2_purpose": op.purpose,
    }
    if cross_section_metadata is not None or sweep_metadata is not None:
        record["v2_curve_sweep_modifier"] = {
            "method": "sampled_curve_swept_profile_alias_v1",
            "target_primitive": "swept_profile",
            **(
                {
                    "cross_section_source_parameter": cross_section_key,
                    "cross_section_curve": cross_section_metadata,
                }
                if cross_section_metadata is not None
                else {}
            ),
            **(
                {
                    "sweep_source_parameter": path_key,
                    "sweep_curve": sweep_metadata,
                }
                if sweep_metadata is not None
                else {}
            ),
        }
    record = _attach_direct_polybevel_modifier(
        record,
        parameters,
        source_operation=op.op,
        target_primitive="swept_profile",
    )
    if geometry_kernel is not None:
        modifier = dict(record.get("v2_curve_sweep_modifier") or {})
        modifier = {
            "method": modifier.get("method") or "authored_swept_profile_v1",
            "target_primitive": "swept_profile",
            "cross_section_point_count": len(cross_section),
            "sweep_path_point_count": len(sweep_path),
            **modifier,
        }
        return _kernel_profile_record_for_single_source(
            op,
            source_record=record,
            geometry_kernel=geometry_kernel,
            route="shape_ir_v2_solid_swept_profile",
            asset_name="shape_ir_v2_solid_swept_profile_source",
            blueprint_id="shape_ir_v2_solid_swept_profile_source",
            modifier_name="v2_curve_sweep_modifier",
            modifier_payload=modifier,
            kernel_tag="swept_profile_kernel_program",
            profile_kind="swept_profile",
        )
    return record


def _v1_record_for_solid_subdivision_box(op: ShapeOp) -> dict[str, Any]:
    """Lower a ``solid.subdivision_box`` op to a v1 subdivision box."""
    parameters = op.parameters
    width = _float_param(parameters, "width_cm")
    height = _float_param(parameters, "height_cm")
    depth = _float_param(parameters, "depth_cm")
    corner_radii = _fixed_float_tuple_param(parameters, "corner_radii_cm", count=8)
    if "corner_segments" in parameters:
        corner_segments_value = _float_param(parameters, "corner_segments")
        if not corner_segments_value.is_integer():
            raise ValueError("parameter 'corner_segments' must be an integer")
        corner_segments = int(corner_segments_value)
    else:
        corner_segments = 4
    if corner_segments < 1:
        raise ValueError("parameter 'corner_segments' must be >= 1")
    return {
        "primitive_type": "subdivision_box",
        "part": op.target or "body",
        "center": _center_param(parameters),
        "extents": (width, height, depth),
        "corner_radii": corner_radii,
        "corner_segments": corner_segments,
        "tags": [],
        "blend_mode": "union",
        "rounding": 0.0,
        "v2_op": op.op,
        "v2_purpose": op.purpose,
    }


def _v1_record_for_sop_sweep(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None = None,
) -> dict[str, Any]:
    """Lower ``sop.sweep`` to the stable v1 swept profile primitive."""
    record = _v1_record_for_solid_swept_profile(op)
    record["v2_op"] = op.op
    record["tags"] = ["sop_sweep"]
    if geometry_kernel is not None:
        return _kernel_profile_record_for_single_source(
            op,
            source_record=record,
            geometry_kernel=geometry_kernel,
            route="shape_ir_v2_sop_sweep",
            asset_name="shape_ir_v2_sop_sweep_source",
            blueprint_id="shape_ir_v2_sop_sweep_source",
            modifier_name="v2_sweep_modifier",
            modifier_payload={
                "cross_section_point_count": len(record.get("cross_section") or []),
                "sweep_path_point_count": len(record.get("sweep_path") or []),
            },
            kernel_tag="sweep_kernel_program",
            profile_kind="sweep",
        )
    return record


def _polyextrude_distance_param(parameters: dict[str, Any]) -> float:
    for key in ("distance_cm", "distance", "extrude_height_cm", "height_cm"):
        if key in parameters:
            return _float_param(parameters, key)
    return 0.0


def _polyextruded_source_record(
    op: ShapeOp,
    *,
    source: _V1Record,
    axis: str,
    distance: float,
) -> _V1Record:
    record = dict(source)
    source_tags = [str(tag) for tag in record.get("tags", []) if str(tag)]
    source_primitive_type = str(record.get("primitive_type") or "")
    record["part"] = op.target or record.get("part") or "body"
    record["tags"] = [
        *source_tags,
        "sop_polyextrude",
        "source_polyextrude",
        f"polyextrude_axis_{axis}",
    ]
    record["v2_source_op"] = record.get("v2_op")
    record["v2_op"] = op.op
    record["v2_purpose"] = op.purpose

    method = "source_preserving_polyextrude_metadata_v1"
    source_extent: float | None = None
    if abs(distance) > 1e-9:
        sign = 1.0 if distance >= 0.0 else -1.0
        amount = abs(distance)
        if (
            source_primitive_type in _MESH_BACKED_PRIMITIVE_TYPES
            and isinstance(record.get("mesh_vertices"), (list, tuple))
        ):
            mesh_bounds = _record_mesh_vertex_bounds(record)
            if mesh_bounds is None:
                raise ValueError("sop.polyextrude requires a mesh source with valid vertices")
            axis_index = _axis_index(axis)
            source_extent = max(mesh_bounds[1][axis_index] - mesh_bounds[0][axis_index], 1e-6)
            exact_mesh, exact_modifier, exact_failure = _sdf_mesh_planar_cap_extend(
                record,
                depth=amount,
                axis=axis,
                side="positive" if sign >= 0.0 else "negative",
                method="sdf_mesh_planar_cap_polyextrude_v1",
            )
            if exact_mesh is not None and exact_modifier is not None:
                record["center"] = (0.0, 0.0, 0.0)
                record["mesh_vertices"] = [
                    [float(value) for value in vertex]
                    for vertex in exact_mesh.vertices.tolist()
                ]
                record["mesh_faces"] = [
                    [int(value) for value in face]
                    for face in exact_mesh.faces.tolist()
                ]
                record["tags"] = [
                    *list(record.get("tags") or []),
                    "sdf_mesh_axis_polyextrude",
                    "sdf_mesh_planar_cap_extend",
                ]
                method = str(exact_modifier["method"])
                record["v2_polyextrude_exact_mesh_modifier"] = exact_modifier
            else:
                measured_mesh, measured_modifier, measured_failure = _measured_bounds_cap_hull_polyextrude(
                    record,
                    depth=amount,
                    axis=axis,
                    side="positive" if sign >= 0.0 else "negative",
                    method="measured_bounds_cap_hull_polyextrude_v1",
                    fallback_from="sdf_mesh_planar_cap_polyextrude_v1",
                    fallback_reason=exact_failure or "planar_cap_extend_unavailable",
                )
                if measured_mesh is not None and measured_modifier is not None:
                    record["center"] = (0.0, 0.0, 0.0)
                    record["mesh_vertices"] = [
                        [float(value) for value in vertex]
                        for vertex in measured_mesh.vertices.tolist()
                    ]
                    record["mesh_faces"] = [
                        [int(value) for value in face]
                        for face in measured_mesh.faces.tolist()
                    ]
                    record["tags"] = [
                        *list(record.get("tags") or []),
                        "sdf_mesh_axis_polyextrude",
                        "measured_bounds_cap_hull_polyextrude",
                    ]
                    method = str(measured_modifier["method"])
                    record["v2_polyextrude_exact_mesh_modifier"] = measured_modifier
                else:
                    anchor = mesh_bounds[0][axis_index] if sign > 0.0 else mesh_bounds[1][axis_index]
                    scale = (source_extent + amount) / source_extent
                    record_center = _record_center_tuple(record)
                    transformed_vertices: list[list[float]] = []
                    for raw_vertex in record["mesh_vertices"]:
                        if not isinstance(raw_vertex, (list, tuple)) or len(raw_vertex) != 3:
                            raise ValueError("sop.polyextrude requires a mesh source with valid vertices")
                        world_vertex = [
                            float(raw_vertex[index]) + record_center[index]
                            for index in range(3)
                        ]
                        world_vertex[axis_index] = anchor + (world_vertex[axis_index] - anchor) * scale
                        transformed_vertices.append(
                            [
                                world_vertex[index] - record_center[index]
                                for index in range(3)
                            ]
                        )
                    record["mesh_vertices"] = transformed_vertices
                    method = "sdf_mesh_axis_polyextrude_v1"
                    record["v2_polyextrude_fallback"] = {
                        "fallback_from": "measured_bounds_cap_hull_polyextrude_v1",
                        "fallback_chain": [
                            "sdf_mesh_planar_cap_polyextrude_v1",
                            "measured_bounds_cap_hull_polyextrude_v1",
                        ],
                        "fallback_reason": measured_failure or exact_failure or "measured_bounds_cap_hull_unavailable",
                        "exact_polyextrude_failure": exact_failure or "",
                        "measured_polyextrude_failure": measured_failure or "",
                    }
        elif "extents" in record and isinstance(record["extents"], (list, tuple)) and len(record["extents"]) == 3:
            extents = [float(value) for value in record["extents"]]
            extents[_axis_index(axis)] += amount
            record["extents"] = tuple(max(value, 1e-6) for value in extents)
            center = _record_center_tuple(record)
            record["center"] = _add_points(center, _axis_center_shift(axis, sign * amount * 0.5))
            method = "extent_axis_polyextrude_v1"
        elif source_primitive_type == "extruded_profile":
            record["axis"] = axis
            record["extrude_height"] = float(record.get("extrude_height") or 0.0) + amount
            center = _record_center_tuple(record)
            record["center"] = _add_points(center, _axis_center_shift(axis, sign * amount * 0.5))
            method = "extruded_profile_height_polyextrude_v1"

    polyextrude_extra: dict[str, Any] = {}
    exact_mesh_modifier = record.get("v2_polyextrude_exact_mesh_modifier")
    if isinstance(exact_mesh_modifier, dict):
        polyextrude_extra["exact_mesh"] = dict(exact_mesh_modifier)
        for key in (
            "fallback",
            "fallback_from",
            "fallback_reason",
            "side",
            "cap_coordinate_cm",
            "result_cap_coordinate_cm",
            "cap_face_count",
            "cap_vertex_count",
            "cap_boundary_edge_count",
            "measured_cap_vertex_count",
            "source_face_count",
            "source_vertex_count",
            "result_face_count",
            "result_vertex_count",
            "result_watertight",
        ):
            if key in exact_mesh_modifier:
                polyextrude_extra[key] = exact_mesh_modifier[key]
    fallback_modifier = record.get("v2_polyextrude_fallback")
    if isinstance(fallback_modifier, dict):
        polyextrude_extra.update(dict(fallback_modifier))
    record["v2_polyextrude_modifier"] = {
        "method": method,
        "source_primitive_type": source_primitive_type,
        "source_op": record.get("v2_source_op"),
        "axis": axis,
        "distance_cm": distance,
        **({"source_extent_cm": source_extent} if source_extent is not None else {}),
        **polyextrude_extra,
    }
    return record


def _polyextrude_kernel_record_for_source(
    op: ShapeOp,
    *,
    source_record: _V1Record,
    geometry_kernel: Any,
    axis: str,
    distance: float,
) -> _V1Record:
    from ..geometry.shape_ir_lowering import execute_shape_ir_kernel_program

    part = str(op.target or source_record.get("part") or "polyextrude")
    blend_mode = _optional_blend_mode(
        op.parameters,
        default=str(source_record.get("blend_mode") or "union"),
    )
    result = execute_shape_ir_kernel_program(
        geometry_kernel,
        _shape_ir_for_kernel_records(
            (
                _record_with_kernel_semantic_metadata(
                    op,
                    source_record,
                    blend_mode=blend_mode,
                ),
            ),
            asset_name="shape_ir_v2_sop_polyextrude_source",
            blueprint_id="shape_ir_v2_sop_polyextrude_source",
        ),
        program_kind="sop.polyextrude",
        source_index=0,
        semantic_operation="sop.polyextrude",
        polyextrude_axis=axis,
        polyextrude_distance_cm=distance,
        route="shape_ir_v2_sop_polyextrude_source",
    )
    details = dict(result.details)
    modifier: dict[str, Any] = {
        "method": details.get("method") or "kernel_program_polyextrude_v1",
        "source_primitive_type": str(source_record.get("primitive_type") or ""),
        "source_op": source_record.get("v2_op") or source_record.get("v2_source_op"),
        "axis": axis,
        "distance_cm": distance,
        "source_part": str(source_record.get("part") or ""),
    }
    for detail_key, modifier_key in (
        ("fallback", "fallback"),
        ("fallback_from", "fallback_from"),
        ("fallback_reason", "fallback_reason"),
        ("side", "side"),
        ("source_min_cm", "source_min_cm"),
        ("source_max_cm", "source_max_cm"),
        ("source_extent_cm", "source_extent_cm"),
        ("result_min_cm", "result_min_cm"),
        ("result_max_cm", "result_max_cm"),
        ("result_extent_cm", "result_extent_cm"),
        ("cap_coordinate_cm", "cap_coordinate_cm"),
        ("cap_face_count", "cap_face_count"),
        ("cap_vertex_count", "cap_vertex_count"),
        ("cap_boundary_edge_count", "cap_boundary_edge_count"),
        ("polyextrude_source_face_count", "source_face_count"),
        ("polyextrude_source_vertex_count", "source_vertex_count"),
        ("polyextrude_result_face_count", "result_face_count"),
        ("polyextrude_result_vertex_count", "result_vertex_count"),
        ("polyextrude_result_watertight", "result_watertight"),
        ("polyextrude_exact", "exact"),
        ("polyextrude_exact_method", "exact_method"),
        ("polyextrude_result_primitive_type", "result_primitive_type"),
        ("polyextrude_result_axis", "result_axis"),
        ("polyextrude_result_extents", "result_extents"),
        ("polyextrude_result_radius", "result_radius"),
        ("polyextrude_result_height", "result_height"),
        ("polyextrude_result_profile_point_count", "result_profile_point_count"),
        ("polyextrude_result_start_scale", "result_start_scale"),
        ("polyextrude_result_end_scale", "result_end_scale"),
        ("polyextrude_side", "side"),
    ):
        if detail_key in details:
            modifier[modifier_key] = _metadata_safe_value(details[detail_key])

    record = _kernel_mesh_record_for_result(
        op,
        result=result,
        part=part,
        tags=[
            *list(source_record.get("tags") or []),
            "sop_polyextrude",
            "polyextrude_kernel_program",
            f"polyextrude_axis_{axis}",
        ],
        blend_mode=blend_mode,
        modifier_name="v2_polyextrude_modifier",
        modifier_payload=modifier,
        geometry_kernel=geometry_kernel,
        source_records=(source_record,),
        kernel_selection=_kernel_selection_source(geometry_kernel),
        result_primitive_type="profile_mesh",
    )
    record["v2_source_op"] = source_record.get("v2_op")
    semantic_metadata = dict(record.get("semantic_metadata") or {})
    semantic_metadata["operation"] = "sop.polyextrude"
    semantic_metadata["operation_id"] = f"{op.op}:{part}:{source_record.get('part') or 'source'}"
    semantic_metadata["polyextrude"] = _metadata_safe_value(modifier)
    record["semantic_metadata"] = semantic_metadata
    return record


def _v1_record_for_sop_polyextrude(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None = None,
) -> _V1Lowering:
    """Lower ``sop.polyextrude`` to the stable v1 extruded profile primitive."""
    parameters = op.parameters
    if "source" in parameters:
        source_record = _single_source_record_from_param(
            parameters["source"],
            geometry_kernel=geometry_kernel,
        )
        axis = _axis_param(parameters)
        distance = _polyextrude_distance_param(parameters)
        if source_record.get("v2_context_aggregate"):
            records = tuple(
                _polyextruded_source_record(
                    op,
                    source=context_source,
                    axis=axis,
                    distance=distance,
                )
            for context_source in _context_expanded_kernel_source_records(
                (source_record,),
                context_tag="source_context_polyextrude_child",
                metadata_key="v2_polyextrude_context",
            )
            )
            if geometry_kernel is not None:
                return _kernel_union_record_for_records(
                    op,
                    records=records,
                    geometry_kernel=geometry_kernel,
                    route="shape_ir_v2_sop_polyextrude_compound_context",
                    asset_name="shape_ir_v2_sop_polyextrude_source",
                    blueprint_id="shape_ir_v2_sop_polyextrude_source",
                    modifier_name="v2_polyextrude_modifier",
                    modifier_payload={
                        "axis": axis,
                        "distance_cm": distance,
                        "context_record_count": len(records),
                    },
                    part=op.target or source_record.get("part") or "body",
                    tags=[
                        *[str(tag) for tag in source_record.get("tags", []) if str(tag)],
                        "sop_polyextrude",
                        "source_context_polyextrude",
                        f"polyextrude_axis_{axis}",
                    ],
                    final_blend_mode=str(
                        source_record.get("blend_mode")
                        or _optional_blend_mode(parameters)
                    ),
                    kernel_tag="polyextrude_kernel_program",
            )
            return records

        if geometry_kernel is not None and "center" not in parameters:
            return _polyextrude_kernel_record_for_source(
                op,
                source_record=source_record,
                geometry_kernel=geometry_kernel,
                axis=axis,
                distance=distance,
            )

        record = _polyextruded_source_record(
            op,
            source=source_record,
            axis=axis,
            distance=distance,
        )
        if "center" in parameters:
            record["center"] = _center_param(parameters)
        modifier = dict(record["v2_polyextrude_modifier"])
        if geometry_kernel is not None:
            return _kernel_import_record_for_single_source(
                op,
                source_record=record,
                geometry_kernel=geometry_kernel,
                route="shape_ir_v2_sop_polyextrude_source",
                asset_name="shape_ir_v2_sop_polyextrude_source",
                blueprint_id="shape_ir_v2_sop_polyextrude_source",
                modifier_name="v2_polyextrude_modifier",
                modifier_payload=modifier,
                kernel_tag="polyextrude_kernel_program",
            )
        return record
    record = _v1_record_for_solid_extruded_profile(op)
    record["v2_op"] = op.op
    record["tags"] = ["sop_polyextrude"]
    if geometry_kernel is not None:
        return _kernel_import_record_for_single_source(
            op,
            source_record=record,
            geometry_kernel=geometry_kernel,
            route="shape_ir_v2_sop_polyextrude",
            asset_name="shape_ir_v2_sop_polyextrude_source",
            blueprint_id="shape_ir_v2_sop_polyextrude_source",
            modifier_name="v2_polyextrude_modifier",
            modifier_payload={
                "profile_point_count": len(record.get("profile_polygon") or []),
                "extrude_height": record.get("extrude_height"),
                "axis": record.get("axis"),
            },
            kernel_tag="polyextrude_kernel_program",
        )
    return record


def _v1_record_for_sop_boolean(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None = None,
) -> dict[str, Any]:
    """Lower ``sop.boolean`` by carrying the requested v1 blend mode."""
    operation = _string_param(
        op.parameters,
        "operation",
        allowed={"union", "subtract", "intersect"},
    )
    source_sequence = _boolean_source_sequence(op.parameters)
    if source_sequence is not None:
        if len(source_sequence) < 2:
            raise ValueError("sop.boolean requires at least two sources for boolean lowering")
        records = tuple(
            record
            for index, source in enumerate(source_sequence)
            for record in _boolean_operand_records(
                op,
                source,
                operation=operation,
                blend_mode=(
                    "union" if index == 0 or operation == "union" else operation
                ),
                geometry_kernel=geometry_kernel,
            )
        )
        if geometry_kernel is not None:
            return _kernel_boolean_record_for_records(
                op,
                source_records=records,
                operation=operation,
                geometry_kernel=geometry_kernel,
                route="shape_ir_v2_sop_boolean_multi_source",
                asset_name="shape_ir_v2_sop_boolean_multi_source",
                blueprint_id="shape_ir_v2_sop_boolean_multi_source",
                modifier_name="v2_sop_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "source_count": len(records),
                    "source_parameter": "sources" if "sources" in op.parameters else "source",
                },
                kernel_tag="sop_boolean_multi_source_kernel_program",
                operation_tag="sop_boolean",
                component="boolean_multi_source_operation",
                region=f"{op.target or 'body'}.{operation}",
            )
        return records
    tool_key = _boolean_tool_param_key(op.parameters)
    if "source" in op.parameters and tool_key is not None and "target" not in op.parameters:
        source_records = _boolean_operand_records(
            op,
            op.parameters["source"],
            operation=operation,
            blend_mode="union",
            geometry_kernel=geometry_kernel,
        )
        cutter_records = _boolean_operand_records(
            op,
            op.parameters[tool_key],
            operation=operation,
            blend_mode="union" if operation == "union" else operation,
            geometry_kernel=geometry_kernel,
        )
        records = (*source_records, *cutter_records)
        source_record = source_records[0]
        if geometry_kernel is not None:
            return _kernel_boolean_record_for_records(
                op,
                source_records=records,
                operation=operation,
                geometry_kernel=geometry_kernel,
                route="shape_ir_v2_sop_boolean_source_tool",
                asset_name="shape_ir_v2_sop_boolean_source_tool",
                blueprint_id="shape_ir_v2_sop_boolean_source_tool",
                modifier_name="v2_sop_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "source_parameter": "source",
                    "tool_parameter": tool_key,
                },
                kernel_tag="sop_boolean_source_tool_kernel_program",
                operation_tag="sop_boolean",
                component="boolean_source_tool_operation",
                region=f"{op.target or source_record.get('part') or 'body'}.{operation}",
            )
        return records
    record = _record_with_source(
        op,
        "sop_boolean",
        f"boolean_{operation}",
        geometry_kernel=geometry_kernel,
    )
    seam_group = str(
        op.parameters.get("seam_group")
        or op.parameters.get("seam")
        or f"{op.target or record.get('part') or 'body'}_{operation}_seam"
    )
    record["blend_mode"] = operation
    seam_groups: list[dict[str, Any]] = []
    for index, name in enumerate(
        (
            seam_group,
            *_semantic_boolean_seam_aliases(
                op,
                seam_group=seam_group,
                operation=operation,
            ),
        )
    ):
        group = {
            "name": name,
            "operation": operation,
            "source_op": record.get("v2_source_op") or op.op,
            "target": op.target or record.get("part") or "body",
        }
        if index > 0:
            group["alias_for"] = seam_group
        seam_groups.append(group)
    record["boolean_seam_groups"] = [
        *list(record.get("boolean_seam_groups") or []),
        *seam_groups,
    ]
    _attach_group_lists_to_v2_metadata(record)
    _with_boolean_polybevel_if_requested(
        record,
        op=op,
        operation=operation,
        blend_mode=operation,
        seam_group=seam_group,
    )
    if geometry_kernel is not None:
        target_record = (
            _single_source_record_from_param(
                op.parameters["target"],
                geometry_kernel=geometry_kernel,
            )
            if "target" in op.parameters
            else None
        )
        if target_record is not None:
            cutter_records = _boolean_operand_records(
                op,
                record,
                operation=operation,
                blend_mode=operation,
                geometry_kernel=geometry_kernel,
            )
            if len(cutter_records) > 1:
                return _kernel_source_feature_records_boolean_record(
                    op,
                    source_record=target_record,
                    feature_records=cutter_records,
                    geometry_kernel=geometry_kernel,
                    route="shape_ir_v2_sop_boolean_contextual",
                    asset_name="shape_ir_v2_sop_boolean_contextual_source",
                    blueprint_id="shape_ir_v2_sop_boolean_contextual_source",
                    modifier_name="v2_sop_boolean_modifier",
                    modifier_payload={
                        "operation": operation,
                        "seam_group": seam_group,
                        "contextual_target": True,
                    },
                    kernel_tag="sop_boolean_contextual_kernel_program",
                    operation_tag="sop_boolean",
                    component="boolean_contextual_operation",
                    region=(
                        f"{target_record.get('part') or op.target or 'body'}."
                        f"{operation}"
                    ),
                )
            return _kernel_source_cutter_boolean_record(
                op,
                source_record=target_record,
                cutter_record=cutter_records[0],
                geometry_kernel=geometry_kernel,
                route="shape_ir_v2_sop_boolean_contextual",
                asset_name="shape_ir_v2_sop_boolean_contextual_source",
                blueprint_id="shape_ir_v2_sop_boolean_contextual_source",
                modifier_name="v2_sop_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "seam_group": seam_group,
                    "contextual_target": True,
                },
                kernel_tag="sop_boolean_contextual_kernel_program",
                operation_tag="sop_boolean",
                component="boolean_contextual_operation",
                region=f"{target_record.get('part') or op.target or 'body'}.{operation}",
            )
        return _kernel_import_record_for_single_source(
            op,
            source_record=record,
            geometry_kernel=geometry_kernel,
            route="shape_ir_v2_sop_boolean",
            asset_name="shape_ir_v2_sop_boolean_source",
            blueprint_id="shape_ir_v2_sop_boolean_source",
            modifier_name="v2_sop_boolean_modifier",
            modifier_payload={
                "operation": operation,
                "seam_group": seam_group,
            },
            kernel_tag="sop_boolean_kernel_program",
        )
    return record


def _v1_record_for_op_boolean_blend(
    op: ShapeOp,
    operation: str,
    *,
    geometry_kernel: Any | None = None,
) -> _V1Lowering:
    """Lower semantic boolean ops to a source primitive with v1 blend mode."""
    source_sequence = _boolean_source_sequence(op.parameters)
    if source_sequence is not None:
        if len(source_sequence) < 2:
            raise ValueError(f"{op.op} requires at least two sources for boolean lowering")
        records = tuple(
            record
            for index, source in enumerate(source_sequence)
            for record in _boolean_operand_records(
                op,
                source,
                operation=operation,
                blend_mode=(
                    "union" if index == 0 or operation == "union" else operation
                ),
                geometry_kernel=geometry_kernel,
            )
        )
        if geometry_kernel is not None:
            return _kernel_boolean_record_for_records(
                op,
                source_records=records,
                operation=operation,
                geometry_kernel=geometry_kernel,
                route=f"shape_ir_v2_{_op_tag_token(op.op)}_multi_source_boolean",
                asset_name=f"shape_ir_v2_{_op_tag_token(op.op)}_multi_source_boolean_source",
                blueprint_id=f"shape_ir_v2_{_op_tag_token(op.op)}_multi_source_boolean_source",
                modifier_name="v2_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "semantic_op": op.op,
                    "source_count": len(records),
                    "source_parameter": "sources" if "sources" in op.parameters else "source",
                },
                kernel_tag="boolean_multi_source_kernel_program",
                operation_tag=_op_tag_token(op.op),
                component="boolean_multi_source_operation",
                region=f"{op.target or 'body'}.{operation}",
            )
        return records

    tool_key = _boolean_tool_param_key(op.parameters)
    if "target" in op.parameters and tool_key is not None and "source" not in op.parameters:
        source_records = _boolean_operand_records(
            op,
            op.parameters["target"],
            operation=operation,
            blend_mode="union",
            geometry_kernel=geometry_kernel,
        )
        cutter_records = _boolean_operand_records(
            op,
            op.parameters[tool_key],
            operation=operation,
            blend_mode="union" if operation == "union" else operation,
            geometry_kernel=geometry_kernel,
        )
        records = (*source_records, *cutter_records)
        source_record = source_records[0]
        if geometry_kernel is not None:
            return _kernel_boolean_record_for_records(
                op,
                source_records=records,
                operation=operation,
                geometry_kernel=geometry_kernel,
                route=f"shape_ir_v2_{_op_tag_token(op.op)}_target_tool_boolean",
                asset_name=f"shape_ir_v2_{_op_tag_token(op.op)}_target_tool_boolean_source",
                blueprint_id=f"shape_ir_v2_{_op_tag_token(op.op)}_target_tool_boolean_source",
                modifier_name="v2_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "semantic_op": op.op,
                    "contextual_target": True,
                    "tool_parameter": tool_key,
                },
                kernel_tag="boolean_target_tool_kernel_program",
                operation_tag=_op_tag_token(op.op),
                component="boolean_contextual_operation",
                region=f"{op.target or source_record.get('part') or 'body'}.{operation}",
            )
        return records

    if "source" in op.parameters and tool_key is not None and "target" not in op.parameters:
        source_records = _boolean_operand_records(
            op,
            op.parameters["source"],
            operation=operation,
            blend_mode="union",
            geometry_kernel=geometry_kernel,
        )
        cutter_records = _boolean_operand_records(
            op,
            op.parameters[tool_key],
            operation=operation,
            blend_mode="union" if operation == "union" else operation,
            geometry_kernel=geometry_kernel,
        )
        records = (*source_records, *cutter_records)
        source_record = source_records[0]
        if geometry_kernel is not None:
            return _kernel_boolean_record_for_records(
                op,
                source_records=records,
                operation=operation,
                geometry_kernel=geometry_kernel,
                route=f"shape_ir_v2_{_op_tag_token(op.op)}_source_tool_boolean",
                asset_name=f"shape_ir_v2_{_op_tag_token(op.op)}_source_tool_boolean_source",
                blueprint_id=f"shape_ir_v2_{_op_tag_token(op.op)}_source_tool_boolean_source",
                modifier_name="v2_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "semantic_op": op.op,
                    "source_parameter": "source",
                    "tool_parameter": tool_key,
                },
                kernel_tag="boolean_source_tool_kernel_program",
                operation_tag=_op_tag_token(op.op),
                component="boolean_source_tool_operation",
                region=f"{op.target or source_record.get('part') or 'body'}.{operation}",
            )
        return records

    if "source" not in op.parameters:
        raise ValueError(f"parameter 'source' is required for {op.op} v1 lowering")
    record = _record_with_source(
        op,
        _op_tag_token(op.op),
        f"boolean_{operation}",
        geometry_kernel=geometry_kernel,
    )
    record["blend_mode"] = operation
    if (
        operation in {"subtract", "intersect"}
        or op.parameters.get("seam_group")
        or op.parameters.get("seam")
    ):
        seam_group = _seam_group_name(op, f"{operation}_seam")
        _with_boolean_seam(
            record,
            op=op,
            operation=operation,
            seam_group=seam_group,
        )
        _with_boolean_polybevel_if_requested(
            record,
            op=op,
            operation=operation,
            blend_mode=operation,
            seam_group=seam_group,
        )
    if geometry_kernel is not None:
        target_record = (
            _single_source_record_from_param(
                op.parameters["target"],
                geometry_kernel=geometry_kernel,
            )
            if "target" in op.parameters
            else None
        )
        if target_record is not None:
            cutter_records = _boolean_operand_records(
                op,
                record,
                operation=operation,
                blend_mode=operation,
                geometry_kernel=geometry_kernel,
            )
            if len(cutter_records) > 1:
                return _kernel_source_feature_records_boolean_record(
                    op,
                    source_record=target_record,
                    feature_records=cutter_records,
                    geometry_kernel=geometry_kernel,
                    route=f"shape_ir_v2_{_op_tag_token(op.op)}_contextual_boolean",
                    asset_name=(
                        f"shape_ir_v2_{_op_tag_token(op.op)}_contextual_boolean_source"
                    ),
                    blueprint_id=(
                        f"shape_ir_v2_{_op_tag_token(op.op)}_contextual_boolean_source"
                    ),
                    modifier_name="v2_boolean_modifier",
                    modifier_payload={
                        "operation": operation,
                        "semantic_op": op.op,
                        "contextual_target": True,
                    },
                    kernel_tag="boolean_contextual_kernel_program",
                    operation_tag=_op_tag_token(op.op),
                    component="boolean_contextual_operation",
                    region=(
                        f"{target_record.get('part') or op.target or 'body'}."
                        f"{operation}"
                    ),
                )
            return _kernel_source_cutter_boolean_record(
                op,
                source_record=target_record,
                cutter_record=cutter_records[0],
                geometry_kernel=geometry_kernel,
                route=f"shape_ir_v2_{_op_tag_token(op.op)}_contextual_boolean",
                asset_name=f"shape_ir_v2_{_op_tag_token(op.op)}_contextual_boolean_source",
                blueprint_id=f"shape_ir_v2_{_op_tag_token(op.op)}_contextual_boolean_source",
                modifier_name="v2_boolean_modifier",
                modifier_payload={
                    "operation": operation,
                    "semantic_op": op.op,
                    "contextual_target": True,
                },
                kernel_tag="boolean_contextual_kernel_program",
                operation_tag=_op_tag_token(op.op),
                component="boolean_contextual_operation",
                region=f"{target_record.get('part') or op.target or 'body'}.{operation}",
            )
        return _kernel_import_record_for_single_source(
            op,
            source_record=record,
            geometry_kernel=geometry_kernel,
            route=f"shape_ir_v2_{_op_tag_token(op.op)}",
            asset_name=f"shape_ir_v2_{_op_tag_token(op.op)}_source",
            blueprint_id=f"shape_ir_v2_{_op_tag_token(op.op)}_source",
            modifier_name="v2_boolean_modifier",
            modifier_payload={
                "operation": operation,
                "semantic_op": op.op,
            },
            kernel_tag="boolean_kernel_program",
        )
    return record


def _v1_record_for_op_union(
    op: ShapeOp,
    *,
    geometry_kernel: Any | None = None,
) -> dict[str, Any]:
    """Lower ``op.union`` to an executable v1 union operand."""
    return _v1_record_for_op_boolean_blend(op, "union", geometry_kernel=geometry_kernel)


