def _primitive_from_v1_record(record: _V1Record):
    from ..shape_ir import ShapePrimitive

    primitive_fields = {field.name for field in fields(ShapePrimitive)}
    kwargs = {key: value for key, value in record.items() if key in primitive_fields}
    kwargs["primitive_type"] = str(record.get("primitive_type") or "")
    kwargs["part"] = str(record.get("part") or "hull_source")
    kwargs["center"] = _record_center_tuple(record)
    if not kwargs["primitive_type"]:
        raise ValueError("hull source record is missing primitive_type")
    semantic_metadata = kwargs.get("semantic_metadata")
    if isinstance(semantic_metadata, dict):
        semantic_metadata = dict(semantic_metadata)
    elif semantic_metadata:
        semantic_metadata = {"raw_semantic_metadata": _metadata_safe_value(semantic_metadata)}
    else:
        semantic_metadata = {}
    semantic_metadata.setdefault("source_shape_primitive", _source_shape_primitive_metadata(record))
    kwargs["semantic_metadata"] = semantic_metadata
    return ShapePrimitive(**kwargs)


def _resolve_lowering_geometry_kernel(geometry_kernel: Any | None = None) -> Any:
    if geometry_kernel is not None:
        return geometry_kernel
    scoped_kernel = _LOWERING_GEOMETRY_KERNEL.get()
    if scoped_kernel is not None:
        return scoped_kernel
    from ..geometry.kernel import resolve_geometry_kernel

    return resolve_geometry_kernel()


def _kernel_selection_source(geometry_kernel: Any | None = None) -> str:
    if geometry_kernel is not None or _LOWERING_GEOMETRY_KERNEL.get() is not None:
        return "caller_geometry_kernel"
    return "resolve_geometry_kernel"


def _shape_ir_for_kernel_records(
    records: tuple[_V1Record, ...],
    *,
    asset_name: str,
    blueprint_id: str,
):
    from ..shape_ir import ShapeIR

    primitives = [_primitive_from_v1_record(record) for record in records]
    return ShapeIR(
        asset_name=asset_name,
        family="shape_ir_v2",
        blueprint_id=blueprint_id,
        symmetry_axis=None,
        units="cm",
        primitives=primitives,
        regions=[],
        primitives_used=sorted({primitive.primitive_type for primitive in primitives}),
        part_graph=[],
        signature={},
    )


def _kernel_mesh_record_for_result(
    op: ShapeOp,
    *,
    result: Any,
    part: str,
    tags: list[str],
    blend_mode: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    geometry_kernel: Any,
    component: str | None = None,
    region: str | None = None,
    boolean_seam_groups: list[dict[str, Any]] | None = None,
    bevel_seam_groups: list[dict[str, Any]] | None = None,
    hard_edge_groups: list[dict[str, Any]] | None = None,
    source_records: tuple[dict[str, Any], ...] | None = None,
    kernel_selection: str | None = None,
    result_primitive_type: str = "sdf_mesh",
) -> dict[str, Any]:
    mesh = result.mesh
    record: dict[str, Any] = {
        "primitive_type": result_primitive_type,
        "part": part,
        "center": (0.0, 0.0, 0.0),
        "mesh_vertices": [
            [float(value) for value in vertex]
            for vertex in mesh.vertices.tolist()
        ],
        "mesh_faces": [
            [int(value) for value in face]
            for face in mesh.faces.tolist()
        ],
        "mesh_vertices_space": "world_cm",
        "tags": tags,
        "blend_mode": blend_mode,
        "rounding": 0.0,
        "v2_op": op.op,
        "v2_purpose": op.purpose,
        "semantic_metadata": _kernel_result_semantic_metadata(
            op,
            mesh,
            source_records=source_records,
            result=result,
        ),
        modifier_name: {
            **modifier_payload,
            "kernel": getattr(geometry_kernel, "name", None),
            "kernel_selection": kernel_selection or _kernel_selection_source(geometry_kernel),
            "result_face_count": len(mesh.faces),
            "result_vertex_count": len(mesh.vertices),
            "result_watertight": bool(mesh.is_watertight),
            "kernel_program": result.details,
        },
    }
    if component:
        record["component"] = component
    if region:
        record["region"] = region
    if boolean_seam_groups:
        record["boolean_seam_groups"] = _dedupe_group_records(boolean_seam_groups)
    if bevel_seam_groups:
        record["bevel_seam_groups"] = _dedupe_group_records(bevel_seam_groups)
    if hard_edge_groups:
        record["hard_edge_groups"] = _dedupe_group_records(hard_edge_groups)
    _attach_group_lists_from_sources(record, source_records)
    edge_geometry = result.details.get("kernel_program_edge_treatment_geometry")
    edge_treatment = result.details.get("kernel_program_edge_treatment")
    operand_polybevel_geometry = _kernel_program_operand_polybevel_geometry_applied(result)
    exact_profile_bevel_geometry = _kernel_program_exact_profile_bevel_applied(result)
    edge_geometry_applied = (
        isinstance(edge_geometry, dict)
        and bool(edge_geometry.get("edge_treatment_geometry_applied"))
    ) or (
        isinstance(edge_treatment, dict)
        and bool(edge_treatment.get("edge_treatment_geometry_applied"))
    )
    if (
        (
            edge_geometry_applied
            or operand_polybevel_geometry is not None
            or exact_profile_bevel_geometry is not None
        )
        and isinstance(record.get("v2_polybevel_modifier"), dict)
    ):
        record["v2_polybevel_modifier"] = {
            **dict(record["v2_polybevel_modifier"]),
            **(operand_polybevel_geometry or {}),
            **(exact_profile_bevel_geometry or {}),
            "geometry_applied": True,
            "result_face_count": len(mesh.faces),
            "result_vertex_count": len(mesh.vertices),
            "result_watertight": bool(mesh.is_watertight),
        }
    semantic_metadata = record.get("semantic_metadata")
    semantic_metadata = dict(semantic_metadata) if isinstance(semantic_metadata, dict) else {}
    v2_metadata = semantic_metadata.get(_V2_PROVENANCE_METADATA_KEY)
    v2_metadata = dict(v2_metadata) if isinstance(v2_metadata, dict) else {}
    v2_metadata[modifier_name] = _metadata_safe_value(record[modifier_name])
    if isinstance(record.get("v2_polybevel_modifier"), dict):
        v2_metadata["v2_polybevel_modifier"] = _metadata_safe_value(record["v2_polybevel_modifier"])
    semantic_metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    record["semantic_metadata"] = semantic_metadata
    _attach_group_lists_to_v2_metadata(record)
    return record


def _generated_mesh_record_for_mesh(
    op: ShapeOp,
    *,
    mesh: Any,
    part: str,
    center: tuple[float, float, float] = (0.0, 0.0, 0.0),
    tags: list[str],
    blend_mode: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    component: str | None = None,
    region: str | None = None,
    boolean_seam_groups: list[dict[str, Any]] | None = None,
    bevel_seam_groups: list[dict[str, Any]] | None = None,
    hard_edge_groups: list[dict[str, Any]] | None = None,
    source_records: tuple[dict[str, Any], ...] | None = None,
) -> dict[str, Any]:
    modifier = {
        **modifier_payload,
        "result_face_count": len(mesh.faces),
        "result_vertex_count": len(mesh.vertices),
        "result_watertight": bool(mesh.is_watertight),
    }
    semantic_metadata = _kernel_result_semantic_metadata(
        op,
        mesh,
        source_records=source_records,
    )
    v2_metadata = semantic_metadata.get(_V2_PROVENANCE_METADATA_KEY)
    v2_metadata = dict(v2_metadata) if isinstance(v2_metadata, dict) else {}
    v2_metadata[modifier_name] = _metadata_safe_value(modifier)
    semantic_metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    record: dict[str, Any] = {
        "primitive_type": "sdf_mesh",
        "part": part,
        "center": center,
        "mesh_vertices": [
            [float(value) for value in vertex]
            for vertex in mesh.vertices.tolist()
        ],
        "mesh_faces": [
            [int(value) for value in face]
            for face in mesh.faces.tolist()
        ],
        "tags": tags,
        "blend_mode": blend_mode,
        "rounding": 0.0,
        "v2_op": op.op,
        "v2_purpose": op.purpose,
        "semantic_metadata": semantic_metadata,
        modifier_name: modifier,
    }
    if component:
        record["component"] = component
    if region:
        record["region"] = region
    if boolean_seam_groups:
        record["boolean_seam_groups"] = _dedupe_group_records(boolean_seam_groups)
    if bevel_seam_groups:
        record["bevel_seam_groups"] = _dedupe_group_records(bevel_seam_groups)
    if hard_edge_groups:
        record["hard_edge_groups"] = _dedupe_group_records(hard_edge_groups)
    _attach_group_lists_from_sources(record, source_records)
    _attach_group_lists_to_v2_metadata(record)
    return record


def _demote_baked_sdf_mesh_kernel_source_modifiers(
    record: dict[str, Any],
    *,
    preserve_keys: set[str] | None = None,
) -> dict[str, Any]:
    copied = dict(record)
    if (
        copied.get("primitive_type") not in _MESH_BACKED_PRIMITIVE_TYPES
        or not copied.get("mesh_vertices")
        or not copied.get("mesh_faces")
    ):
        return copied

    baked_modifiers: dict[str, Any] = {}
    for key in (
        "v2_polybevel_modifier",
        "bevel_seam_groups",
        "v2_subdivision_modifier",
        "v2_remesh_modifier",
        "remesh_target_edge_length_cm",
    ):
        if preserve_keys and key in preserve_keys:
            continue
        value = copied.pop(key, None)
        if value not in (None, "", (), [], {}):
            baked_modifiers[key] = _metadata_safe_value(value)
    subdivision_levels = copied.pop("subdivision_levels", None)
    if subdivision_levels not in (None, "", (), [], {}):
        with suppress(TypeError, ValueError):
            if int(subdivision_levels) > 0:
                baked_modifiers["subdivision_levels"] = int(subdivision_levels)

    if not baked_modifiers:
        return copied

    metadata = copied.get("semantic_metadata")
    metadata = deepcopy(metadata) if isinstance(metadata, dict) else {}
    existing = metadata.get("shape_ir_v2_baked_source_modifiers")
    existing = dict(existing) if isinstance(existing, dict) else {}
    metadata["shape_ir_v2_baked_source_modifiers"] = {
        **existing,
        **baked_modifiers,
    }
    copied["semantic_metadata"] = metadata
    return copied


def _kernel_operand_baked_modifier_preserve_keys(record: dict[str, Any]) -> set[str] | None:
    preserve: set[str] = set()
    polybevel = record.get("v2_polybevel_modifier")
    if isinstance(polybevel, dict) and bool(polybevel.get("geometry_applied")):
        preserve.add("v2_polybevel_modifier")
    return preserve or None


def _record_with_kernel_semantic_metadata(
    op: ShapeOp,
    record: dict[str, Any],
    *,
    blend_mode: str | None = None,
    preserve_baked_sdf_mesh_modifier_keys: set[str] | None = None,
) -> dict[str, Any]:
    copied = _demote_baked_sdf_mesh_kernel_source_modifiers(
        record,
        preserve_keys=preserve_baked_sdf_mesh_modifier_keys,
    )
    if blend_mode is not None:
        copied["blend_mode"] = blend_mode

    metadata = copied.get("semantic_metadata")
    if isinstance(metadata, dict):
        metadata = deepcopy(metadata)
    elif metadata:
        metadata = {"raw_semantic_metadata": _metadata_safe_value(metadata)}
    else:
        metadata = {}

    v2_metadata = metadata.get(_V2_PROVENANCE_METADATA_KEY)
    if isinstance(v2_metadata, dict):
        v2_metadata = dict(v2_metadata)
    else:
        v2_metadata = {}
    v2_metadata.setdefault("v2_op", copied.get("v2_op") or op.op)
    v2_metadata.setdefault(
        "source_operation",
        copied.get("v2_source_op") or copied.get("v2_op") or op.op,
    )
    for key, value in copied.items():
        if key.startswith("v2_") and value not in (None, "", (), [], {}):
            v2_metadata.setdefault(key, _metadata_safe_value(value))

    metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    copied["semantic_metadata"] = metadata
    return copied


