def _kernel_result_metadata_from_mesh(mesh: Any) -> dict[str, Any]:
    metadata = getattr(mesh, "metadata", None)
    if not isinstance(metadata, dict):
        return {}
    out: dict[str, Any] = {}
    for key in sorted(_KERNEL_RESULT_METADATA_KEYS):
        value = metadata.get(key)
        if value not in (None, "", (), [], {}):
            out[key] = _metadata_safe_value(value)
    return out


def _kernel_result_metadata_from_program_result(result: Any | None, mesh: Any) -> dict[str, Any]:
    out = _kernel_result_metadata_from_mesh(mesh)
    details = getattr(result, "details", None)
    if not isinstance(details, dict):
        return _normalize_kernel_result_face_operation_summary(out, mesh)
    for key in sorted(_KERNEL_PROGRAM_RESULT_DETAIL_KEYS):
        value = details.get(key)
        if value not in (None, "", (), [], {}):
            out[key] = _metadata_safe_value(value)
    return _normalize_kernel_result_face_operation_summary(out, mesh)


def _normalize_kernel_result_face_operation_summary(
    metadata: dict[str, Any],
    mesh: Any,
) -> dict[str, Any]:
    summary = metadata.get("face_operation_summary")
    if not isinstance(summary, dict):
        return metadata
    try:
        emitted_face_count = int(len(mesh.faces))
    except (AttributeError, TypeError, ValueError):
        return metadata
    previous_face_count = int(summary.get("face_count") or 0)
    if previous_face_count == emitted_face_count:
        return metadata
    source = str(summary.get("source") or "")
    operations = summary.get("operations")
    if "whole_result" not in source or not isinstance(operations, dict) or len(operations) != 1:
        return metadata
    operation_id = next(iter(operations.keys()))
    normalized_summary = {
        **dict(summary),
        "face_count": emitted_face_count,
        "operations": {str(operation_id): emitted_face_count},
        "normalized_to_emitted_mesh": True,
        "previous_face_count": previous_face_count,
        "normalization_reason": "whole_result_operation_summary_from_intermediate_mesh",
    }
    normalized = {**metadata, "face_operation_summary": normalized_summary}
    for attribution_key in (
        "lathe_kernel_program_face_operation_attribution",
        "kernel_program_face_operation_attribution",
    ):
        attribution = normalized.get(attribution_key)
        if isinstance(attribution, dict):
            normalized[attribution_key] = {
                **dict(attribution),
                "result_face_count": emitted_face_count,
                "normalized_to_emitted_mesh": True,
                "previous_result_face_count": previous_face_count,
            }
    return normalized


def _kernel_result_semantic_metadata(
    op: ShapeOp,
    mesh: Any,
    *,
    source_records: tuple[dict[str, Any], ...] | None = None,
    result: Any | None = None,
) -> dict[str, Any]:
    v2_metadata: dict[str, Any] = {"v2_op": op.op}
    if op.target:
        v2_metadata["target"] = op.target
    if op.purpose:
        v2_metadata["v2_purpose"] = op.purpose
    metadata: dict[str, Any] = {_V2_PROVENANCE_METADATA_KEY: v2_metadata}

    kernel_metadata = _kernel_result_metadata_from_program_result(result, mesh)
    if kernel_metadata:
        metadata[_KERNEL_RESULT_METADATA_KEY] = kernel_metadata

    if source_records:
        sources = [
            _source_shape_primitive_metadata(record)
            for record in source_records
        ]
        if sources:
            metadata[_SOURCE_SHAPE_PRIMITIVES_METADATA_KEY] = sources
            if len(sources) == 1:
                metadata["source_shape_primitive"] = sources[0]
    return metadata


def _component_assembly_record_for_v1_records(
    op: ShapeOp,
    *,
    records: tuple[dict[str, Any], ...],
    part: str,
    assembly_kind: str,
    tags: list[str],
    blend_mode: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    component: str,
    region: str,
) -> dict[str, Any] | None:
    if not records:
        return None
    final_blend_mode = str(blend_mode or "union")
    if final_blend_mode not in {"union", "subtract", "intersect"}:
        return None
    component_blend_modes: dict[str, int] = {}
    component_primitive_types: dict[str, int] = {}
    for record in records:
        component_blend = str(record.get("blend_mode") or "union")
        if component_blend not in {"union", "subtract", "intersect"}:
            return None
        primitive_type = str(record.get("primitive_type") or "")
        if not primitive_type:
            return None
        component_blend_modes[component_blend] = component_blend_modes.get(component_blend, 0) + 1
        component_primitive_types[primitive_type] = component_primitive_types.get(primitive_type, 0) + 1
    modifier = {
        **_metadata_safe_value(modifier_payload),
        "component_record_count": len(records),
        "component_blend_modes": component_blend_modes,
        "component_primitive_types": component_primitive_types,
        **_source_record_provenance_payload(records),
    }
    sources = [_source_shape_primitive_metadata(record) for record in records]
    metadata: dict[str, Any] = {
        _V2_PROVENANCE_METADATA_KEY: {
            "v2_op": op.op,
            modifier_name: modifier,
        },
        _SOURCE_SHAPE_PRIMITIVES_METADATA_KEY: sources,
    }
    if len(sources) == 1:
        metadata["source_shape_primitive"] = sources[0]
    return {
        "primitive_type": "component_assembly",
        "part": part,
        "center": (0.0, 0.0, 0.0),
        "assembly_kind": assembly_kind,
        "assembly_primitives": [deepcopy(record) for record in records],
        "component": component,
        "region": region,
        "tags": tags,
        "blend_mode": final_blend_mode,
        "rounding": 0.0,
        "v2_op": op.op,
        "v2_purpose": op.purpose,
        modifier_name: modifier,
        "semantic_metadata": metadata,
    }


def _record_group_list(
    records: tuple[dict[str, Any], ...],
    key: str,
) -> list[dict[str, Any]]:
    return [
        dict(group)
        for record in records
        for group in list(record.get(key) or [])
        if isinstance(group, dict)
    ]


def _dedupe_group_records(groups: list[dict[str, Any]]) -> list[dict[str, Any]]:
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for group in groups:
        if not isinstance(group, dict):
            continue
        payload = dict(group)
        key = repr(_metadata_safe_value(payload))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(payload)
    return deduped


def _dedupe_text_values(values: list[Any]) -> list[str]:
    deduped: list[str] = []
    for value in values:
        text = str(value or "").strip()
        if text and text not in deduped:
            deduped.append(text)
    return deduped


def _source_record_modifier_method_entries(records: tuple[dict[str, Any], ...]) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, record in enumerate(records):
        record_op = str(record.get("v2_op") or record.get("v2_source_op") or "").strip()
        record_part = str(record.get("part") or "").strip()
        candidates: list[tuple[str, Any]] = [
            (key, value)
            for key, value in record.items()
            if key.startswith("v2_") and isinstance(value, dict)
        ]
        metadata = record.get("semantic_metadata")
        if isinstance(metadata, dict):
            v2_metadata = metadata.get(_V2_PROVENANCE_METADATA_KEY)
            if isinstance(v2_metadata, dict):
                candidates.extend(
                    (key, value)
                    for key, value in v2_metadata.items()
                    if key.startswith("v2_") and isinstance(value, dict)
                )
        for field, payload in candidates:
            method = str(payload.get("method") or "").strip()
            kernel_method = str(
                payload.get("kernel_boolean_method")
                or payload.get("kernel_program_method")
                or payload.get("kernel_polyextrude_method")
                or ""
            ).strip()
            source_method = str(
                payload.get("source_modifier_method")
                or payload.get("attachment_modifier_method")
                or payload.get("feature_modifier_method")
                or ""
            ).strip()
            if not (method or kernel_method or source_method):
                continue
            entry: dict[str, Any] = {
                "record_index": index,
                "field": field,
            }
            if record_op:
                entry["source_operation"] = record_op
            if record_part:
                entry["part"] = record_part
            if method:
                entry["method"] = method
            if kernel_method:
                entry["kernel_method"] = kernel_method
            if source_method:
                entry["source_modifier_method"] = source_method
            key = repr(_metadata_safe_value(entry))
            if key in seen:
                continue
            seen.add(key)
            entries.append(entry)
    return entries


def _source_record_provenance_payload(records: tuple[dict[str, Any], ...]) -> dict[str, Any]:
    source_operations = _dedupe_text_values(
        [
            record.get("v2_op") or record.get("v2_source_op")
            for record in records
        ]
    )
    source_primitive_types = _dedupe_text_values(
        [record.get("primitive_type") for record in records]
    )
    source_modifier_methods = _source_record_modifier_method_entries(records)
    source_context_record_count = 0
    for record in records:
        with suppress(TypeError, ValueError):
            source_context_record_count += int(record.get("v2_context_record_count") or 0)
    source_context_parts = _dedupe_text_values(
        [
            part
            for record in records
            for part in record.get("v2_context_parts", [])
        ]
    )
    source_context_primitive_types = _dedupe_text_values(
        [
            primitive_type
            for record in records
            for primitive_type in record.get("v2_context_primitive_types", [])
        ]
    )
    payload: dict[str, Any] = {}
    if source_operations:
        payload["source_operations"] = source_operations
    if source_primitive_types:
        payload["source_primitive_types"] = source_primitive_types
    if source_context_record_count > 0:
        payload["source_context_record_count"] = source_context_record_count
    if source_context_parts:
        payload["source_context_parts"] = source_context_parts
    if source_context_primitive_types:
        payload["source_context_primitive_types"] = source_context_primitive_types
    if source_modifier_methods:
        payload["source_modifier_methods"] = source_modifier_methods
        payload["source_modifier_method_count"] = len(source_modifier_methods)
    return payload


def _materialized_polybevel_modifier_summary(records: tuple[dict[str, Any], ...]) -> dict[str, Any] | None:
    modifiers = [
        dict(record.get("v2_polybevel_modifier") or {})
        for record in records
        if isinstance(record.get("v2_polybevel_modifier"), dict)
    ]
    if not modifiers:
        return None
    target_names = _dedupe_text_values(
        [
            target
            for modifier in modifiers
            for target in (
                [modifier.get("target_seam_groups")]
                if isinstance(modifier.get("target_seam_groups"), str)
                else list(modifier.get("target_seam_groups") or [])
            )
        ]
    )
    widths = [float(modifier.get("width_cm") or 0.0) for modifier in modifiers]
    segments = [int(modifier.get("segments") or 1) for modifier in modifiers]
    source_operations = _dedupe_text_values([modifier.get("source_operation") for modifier in modifiers])
    source_kernels = _dedupe_text_values([modifier.get("kernel") for modifier in modifiers])
    geometry_applied = any(bool(modifier.get("geometry_applied")) for modifier in modifiers)
    construction_methods = _dedupe_text_values(
        [
            method
            for modifier in modifiers
            for method in list(modifier.get("kernel_operand_polybevel_construction_methods") or [])
            if str(method)
        ]
    )
    edge_pairs = _dedupe_text_values(
        [
            edge_pair
            for modifier in modifiers
            for edge_pair in (
                [modifier.get("edge_pairs")]
                if isinstance(modifier.get("edge_pairs"), str)
                else list(modifier.get("edge_pairs") or [])
            )
        ]
    )
    summary = {
        "schema": "lathe.shape_ir_v2.materialized_polybevel_modifier_summary.v1",
        "source_modifier_count": len(modifiers),
        "width_cm": max(widths) if widths else 0.0,
        "segments": max(segments) if segments else 1,
        "target_seam_groups": target_names,
        "source_operations": source_operations,
        "source_kernels": source_kernels,
    }
    if edge_pairs:
        summary["edge_pairs"] = edge_pairs
    if geometry_applied:
        summary["geometry_applied"] = True
        summary["geometry_applied_source"] = "materialized_source_modifier_summary"
    if construction_methods:
        summary["kernel_operand_polybevel_construction_methods"] = construction_methods
    return summary


def _attach_group_lists_from_sources(
    record: dict[str, Any],
    source_records: tuple[dict[str, Any], ...] | None,
) -> dict[str, Any]:
    records = tuple(source_records or ())
    if not records:
        return record
    for key in ("boolean_seam_groups", "bevel_seam_groups", "hard_edge_groups"):
        groups = _record_group_list(records, key)
        if not groups:
            continue
        existing = [
            dict(group)
            for group in list(record.get(key) or [])
            if isinstance(group, dict)
        ]
        record[key] = _dedupe_group_records([*existing, *groups])
    if not isinstance(record.get("v2_polybevel_modifier"), dict):
        modifier = _materialized_polybevel_modifier_summary(records)
        if modifier is not None:
            record["v2_polybevel_modifier"] = modifier
    return record


def _attach_group_lists_to_v2_metadata(record: dict[str, Any]) -> dict[str, Any]:
    metadata = record.get("semantic_metadata")
    metadata = dict(metadata) if isinstance(metadata, dict) else {}
    v2_metadata = metadata.get(_V2_PROVENANCE_METADATA_KEY)
    v2_metadata = dict(v2_metadata) if isinstance(v2_metadata, dict) else {}
    for key, count_key in (
        ("boolean_seam_groups", "boolean_seam_group_count"),
        ("bevel_seam_groups", "bevel_seam_group_count"),
        ("hard_edge_groups", "hard_edge_group_count"),
    ):
        groups = [
            dict(group)
            for group in list(record.get(key) or [])
            if isinstance(group, dict)
        ]
        groups = _dedupe_group_records(groups)
        if not groups:
            continue
        record[key] = groups
        v2_metadata[key] = _metadata_safe_value(groups)
        v2_metadata[count_key] = len(groups)
    metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    record["semantic_metadata"] = metadata
    return record


def _kernel_program_operand_polybevel_geometry_applied(result: Any) -> dict[str, Any] | None:
    details = getattr(result, "details", None)
    if not isinstance(details, dict):
        return None
    operands = details.get("kernel_program_operands")
    if not isinstance(operands, list):
        return None
    applied: list[dict[str, Any]] = []
    for operand in operands:
        if not isinstance(operand, dict):
            continue
        metadata = operand.get("metadata")
        metadata = dict(metadata) if isinstance(metadata, dict) else {}
        direct_polybevel = metadata.get("v2_polybevel_modifier")
        semantic_metadata = metadata.get("semantic_metadata")
        semantic_metadata = dict(semantic_metadata) if isinstance(semantic_metadata, dict) else {}
        shape_v2 = semantic_metadata.get(_V2_PROVENANCE_METADATA_KEY)
        shape_v2 = dict(shape_v2) if isinstance(shape_v2, dict) else {}
        v2_polybevel = direct_polybevel or shape_v2.get("v2_polybevel_modifier")
        if not isinstance(v2_polybevel, dict) or not v2_polybevel:
            continue
        kernel_import = metadata.get("kernel_import")
        kernel_import = dict(kernel_import) if isinstance(kernel_import, dict) else {}
        if not bool(kernel_import.get("construction_geometry_applied")):
            continue
        applied.append(
            {
                "operand_id": str(operand.get("id") or operand.get("operand_id") or ""),
                "part": str(operand.get("part") or ""),
                "primitive_type": str(operand.get("primitive_type") or ""),
                "source_mesh_face_count": int(operand.get("source_mesh_face_count") or 0),
                "source_mesh_vertex_count": int(operand.get("source_mesh_vertex_count") or 0),
                "source_mesh_body_count": int(operand.get("source_mesh_body_count") or 0),
                "construction_methods": [
                    str(method)
                    for method in list(kernel_import.get("construction_methods") or [])
                    if str(method)
                ],
            }
        )
    if not applied:
        return None
    methods = _dedupe_text_values(
        [
            method
            for item in applied
            for method in list(item.get("construction_methods") or [])
        ]
    )
    payload = {
        "geometry_applied": True,
        "geometry_applied_during_kernel_import": True,
        "kernel_operand_geometry_applied_count": len(applied),
        "kernel_operand_geometry_applied_source": "kernel_import.construction_geometry_applied",
        "kernel_operand_polybevel_primitives": _dedupe_text_values(
            [item.get("primitive_type") for item in applied]
        ),
        "kernel_operand_polybevel_parts": _dedupe_text_values(
            [item.get("part") for item in applied]
        ),
        "kernel_operand_polybevel_source_face_count": sum(
            int(item.get("source_mesh_face_count") or 0) for item in applied
        ),
        "kernel_operand_polybevel_source_body_count": sum(
            int(item.get("source_mesh_body_count") or 0) for item in applied
        ),
    }
    if methods:
        payload["kernel_operand_polybevel_construction_methods"] = methods
    return payload


def _kernel_program_exact_profile_bevel_applied(result: Any) -> dict[str, Any] | None:
    details = getattr(result, "details", None)
    if not isinstance(details, dict):
        return None
    final = details.get("kernel_program_exact_profile_cut_final")
    if not isinstance(final, dict):
        return None
    try:
        bevel_face_count = int(final.get("bevel_face_count") or 0)
        chamfer_face_count = int(final.get("chamfer_face_count") or 0)
        profile_cut_count = int(final.get("profile_cut_count") or 0)
        bevel_segments = int(final.get("bevel_segments") or 0)
    except (TypeError, ValueError):
        return None
    if bevel_face_count <= 0 and chamfer_face_count <= 0:
        return None
    payload = {
        "geometry_applied": True,
        "geometry_applied_during_kernel_program": True,
        "exact_profile_cut_bevel_applied": True,
        "exact_profile_cut_method": str(final.get("method") or ""),
        "exact_profile_cut_count": profile_cut_count,
        "exact_profile_cut_bevel_face_count": bevel_face_count,
        "exact_profile_cut_chamfer_face_count": chamfer_face_count,
        "exact_profile_cut_bevel_segments": bevel_segments,
    }
    for source_key, target_key in (
        ("result_face_count", "exact_profile_cut_result_face_count"),
        ("result_vertex_count", "exact_profile_cut_result_vertex_count"),
        ("result_body_count", "exact_profile_cut_result_body_count"),
    ):
        value = final.get(source_key)
        if value not in (None, "", (), [], {}):
            try:
                payload[target_key] = int(value)
            except (TypeError, ValueError):
                pass
    if final.get("result_watertight") is not None:
        payload["exact_profile_cut_result_watertight"] = bool(final.get("result_watertight"))
    return payload


def _attach_v2_field_to_metadata(record: dict[str, Any], key: str) -> dict[str, Any]:
    value = record.get(key)
    if not key.startswith("v2_") or value in (None, "", (), [], {}):
        return _attach_group_lists_to_v2_metadata(record)
    metadata = record.get("semantic_metadata")
    metadata = dict(metadata) if isinstance(metadata, dict) else {}
    v2_metadata = metadata.get(_V2_PROVENANCE_METADATA_KEY)
    v2_metadata = dict(v2_metadata) if isinstance(v2_metadata, dict) else {}
    v2_metadata[key] = _metadata_safe_value(value)
    metadata[_V2_PROVENANCE_METADATA_KEY] = v2_metadata
    record["semantic_metadata"] = metadata
    return _attach_group_lists_to_v2_metadata(record)


def _remove_profile_cut_bevel_marker(record: dict[str, Any]) -> dict[str, Any]:
    polybevel = record.get("v2_polybevel_modifier")
    if isinstance(polybevel, dict) and "profile_cut_bevel" in polybevel:
        polybevel = dict(polybevel)
        polybevel.pop("profile_cut_bevel", None)
        record["v2_polybevel_modifier"] = polybevel
        return _attach_v2_field_to_metadata(record, "v2_polybevel_modifier")
    return _attach_group_lists_to_v2_metadata(record)


def _attach_source_shape_primitive_metadata(
    record: dict[str, Any],
    source_record: dict[str, Any],
) -> dict[str, Any]:
    copied = dict(record)
    metadata = copied.get("semantic_metadata")
    metadata = dict(metadata) if isinstance(metadata, dict) else {}
    metadata["source_shape_primitive"] = _source_shape_primitive_metadata(source_record)
    copied["semantic_metadata"] = metadata
    return copied


def _kernel_import_record_for_single_source(
    op: ShapeOp,
    *,
    source_record: dict[str, Any],
    geometry_kernel: Any,
    route: str,
    asset_name: str,
    blueprint_id: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    kernel_tag: str,
) -> dict[str, Any]:
    from ..geometry.shape_ir_lowering import execute_shape_ir_kernel_program

    polybevel = source_record.get("v2_polybevel_modifier")
    preserve_pending_polybevel = (
        isinstance(polybevel, dict)
        and bool(polybevel)
        and "result_face_count" not in polybevel
        and "kernel_program" not in polybevel
    )
    kernel_import_source_record = source_record
    if (
        modifier_name in _BOOLEAN_MESH_IMPORT_MODIFIER_NAMES
        and source_record.get("mesh_vertices")
        and source_record.get("mesh_faces")
    ):
        kernel_import_source_record = {**source_record, "primitive_type": "boolean_mesh"}
    kernel_source_record = _record_with_kernel_semantic_metadata(
        op,
        kernel_import_source_record,
        preserve_baked_sdf_mesh_modifier_keys=(
            {"v2_polybevel_modifier"}
            if modifier_name == "v2_polybevel_modifier" or preserve_pending_polybevel
            else None
        ),
    )
    result = execute_shape_ir_kernel_program(
        geometry_kernel,
        _shape_ir_for_kernel_records(
            (kernel_source_record,),
            asset_name=asset_name,
            blueprint_id=blueprint_id,
        ),
        program_kind="import",
        source_index=0,
        semantic_operation=op.op,
        route=route,
        backend=getattr(geometry_kernel, "name", None),
    )
    if modifier_name == "v2_polybevel_modifier":
        result_primitive_type = "polybevel_mesh"
    elif modifier_name in _BOOLEAN_MESH_IMPORT_MODIFIER_NAMES:
        result_primitive_type = "boolean_mesh"
    elif modifier_name in _INSTANCE_MESH_MODIFIER_NAMES:
        result_primitive_type = "instance_mesh"
    elif modifier_name in _PROFILE_MESH_IMPORT_MODIFIER_NAMES:
        result_primitive_type = "profile_mesh"
    elif modifier_name in _CONSTRUCTION_FEATURE_MESH_IMPORT_MODIFIER_NAMES:
        result_primitive_type = "construction_feature_mesh"
    elif modifier_name in _EDGE_CONTROL_MESH_IMPORT_MODIFIER_NAMES:
        result_primitive_type = "edge_control_mesh"
    elif modifier_name in _COMPONENT_ASSEMBLY_MESH_IMPORT_MODIFIER_NAMES:
        result_primitive_type = "component_assembly_mesh"
    elif modifier_name in _TERRAIN_MESH_IMPORT_MODIFIER_NAMES:
        result_primitive_type = "terrain_mesh"
    else:
        result_primitive_type = "sdf_mesh"
    record = _kernel_mesh_record_for_result(
        op,
        result=result,
        part=str(source_record.get("part") or op.target or "body"),
        tags=[*list(source_record.get("tags") or []), kernel_tag],
        blend_mode=str(source_record.get("blend_mode") or _optional_blend_mode(op.parameters)),
        modifier_name=modifier_name,
        modifier_payload=modifier_payload,
        geometry_kernel=geometry_kernel,
        component=str(source_record.get("component") or "") or None,
        region=str(source_record.get("region") or "") or None,
        boolean_seam_groups=_record_group_list((source_record,), "boolean_seam_groups"),
        bevel_seam_groups=_record_group_list((source_record,), "bevel_seam_groups"),
        hard_edge_groups=_record_group_list((source_record,), "hard_edge_groups"),
        source_records=(kernel_source_record,),
        result_primitive_type=result_primitive_type,
    )
    if "axis" in source_record:
        record["axis"] = source_record["axis"]
    for key in ("bevel_seam_groups", "v2_polybevel_modifier"):
        value = source_record.get(key)
        if value not in (None, "", (), [], {}):
            if isinstance(value, dict) and isinstance(record.get(key), dict):
                record[key] = {**deepcopy(value), **record[key]}
            else:
                record[key] = deepcopy(value)
    source_primitive_type = str(source_record.get("primitive_type") or "")
    if source_primitive_type in _MESH_BACKED_PRIMITIVE_TYPES:
        record["primitive_type"] = source_primitive_type
    elif source_primitive_type == "component_assembly":
        record["primitive_type"] = "component_assembly_mesh"
    elif source_primitive_type:
        record["primitive_type"] = "kernel_primitive_mesh"
    if modifier_name == "v2_polybevel_modifier":
        record["primitive_type"] = "polybevel_mesh"
    if modifier_name in _BOOLEAN_MESH_IMPORT_MODIFIER_NAMES:
        record["primitive_type"] = "boolean_mesh"
    if modifier_name in _INSTANCE_MESH_MODIFIER_NAMES:
        record["primitive_type"] = "instance_mesh"
    if modifier_name in _PROFILE_MESH_IMPORT_MODIFIER_NAMES:
        record["primitive_type"] = "profile_mesh"
    if modifier_name in _CONSTRUCTION_FEATURE_MESH_IMPORT_MODIFIER_NAMES:
        record["primitive_type"] = "construction_feature_mesh"
    if modifier_name in _EDGE_CONTROL_MESH_IMPORT_MODIFIER_NAMES:
        record["primitive_type"] = "edge_control_mesh"
    if modifier_name in _COMPONENT_ASSEMBLY_MESH_IMPORT_MODIFIER_NAMES:
        record["primitive_type"] = "component_assembly_mesh"
    if modifier_name in _TERRAIN_MESH_IMPORT_MODIFIER_NAMES:
        record["primitive_type"] = "terrain_mesh"
    return _attach_source_shape_primitive_metadata(record, kernel_import_source_record)


def _kernel_profile_record_for_single_source(
    op: ShapeOp,
    *,
    source_record: dict[str, Any],
    geometry_kernel: Any,
    route: str,
    asset_name: str,
    blueprint_id: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    kernel_tag: str,
    profile_kind: str,
) -> dict[str, Any]:
    from ..geometry.shape_ir_lowering import execute_shape_ir_kernel_program

    kernel_source_record = _record_with_kernel_semantic_metadata(op, source_record)
    result = execute_shape_ir_kernel_program(
        geometry_kernel,
        _shape_ir_for_kernel_records(
            (kernel_source_record,),
            asset_name=asset_name,
            blueprint_id=blueprint_id,
        ),
        program_kind="profile_path",
        source_index=0,
        semantic_operation=op.op,
        profile_kind=profile_kind,
        route=route,
        backend=getattr(geometry_kernel, "name", None),
    )
    record = _kernel_mesh_record_for_result(
        op,
        result=result,
        part=str(source_record.get("part") or op.target or "profile"),
        tags=[*list(source_record.get("tags") or []), kernel_tag],
        blend_mode=str(source_record.get("blend_mode") or _optional_blend_mode(op.parameters)),
        modifier_name=modifier_name,
        modifier_payload={
            **modifier_payload,
            "profile_kind": profile_kind,
        },
        geometry_kernel=geometry_kernel,
        component=str(source_record.get("component") or "") or None,
        region=str(source_record.get("region") or "") or None,
        boolean_seam_groups=_record_group_list((source_record,), "boolean_seam_groups"),
        bevel_seam_groups=_record_group_list((source_record,), "bevel_seam_groups"),
        hard_edge_groups=_record_group_list((source_record,), "hard_edge_groups"),
        source_records=(kernel_source_record,),
        result_primitive_type="profile_mesh",
    )
    for key in ("axis", "v2_polybevel_modifier", "bevel_seam_groups"):
        value = source_record.get(key)
        if value not in (None, "", (), [], {}):
            record[key] = deepcopy(value)
    record["primitive_type"] = "profile_mesh"
    return _attach_source_shape_primitive_metadata(record, kernel_source_record)


