def _kernel_union_record_for_records(
    op: ShapeOp,
    *,
    records: tuple[dict[str, Any], ...],
    geometry_kernel: Any,
    route: str,
    asset_name: str,
    blueprint_id: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    part: str,
    tags: list[str],
    final_blend_mode: str,
    kernel_tag: str,
    component: str | None = None,
    region: str | None = None,
    result_primitive_type: str = "boolean_mesh",
) -> dict[str, Any]:
    from ..geometry.shape_ir_lowering import execute_shape_ir_kernel_program

    kernel_records_list: list[dict[str, Any]] = []
    for record in records:
        kernel_records_list.append(
            _record_with_kernel_semantic_metadata(op, record, blend_mode="union")
        )
    kernel_records = tuple(kernel_records_list)
    boolean_seam_groups = _record_group_list(kernel_records, "boolean_seam_groups")
    bevel_seam_groups = _record_group_list(kernel_records, "bevel_seam_groups")
    hard_edge_groups = _record_group_list(kernel_records, "hard_edge_groups")
    result = execute_shape_ir_kernel_program(
        geometry_kernel,
        _shape_ir_for_kernel_records(
            kernel_records,
            asset_name=asset_name,
            blueprint_id=blueprint_id,
        ),
        program_kind="boolean",
        semantic_operation=op.op,
        route=route,
        backend=getattr(geometry_kernel, "name", None),
    )
    kernel_boolean_method = f"source_record_union_{_op_tag_token(op.op)}_v1"
    record = _kernel_mesh_record_for_result(
        op,
        result=result,
        part=part,
        tags=[*tags, kernel_tag],
        blend_mode=final_blend_mode,
        modifier_name=modifier_name,
        modifier_payload={
            **modifier_payload,
            "method": str(modifier_payload.get("method") or kernel_boolean_method),
            "kernel_boolean_method": kernel_boolean_method,
            "source_record_count": len(records),
            **_source_record_provenance_payload(records),
        },
        geometry_kernel=geometry_kernel,
        component=component,
        region=region,
        boolean_seam_groups=boolean_seam_groups,
        bevel_seam_groups=bevel_seam_groups,
        hard_edge_groups=hard_edge_groups,
        source_records=kernel_records,
        result_primitive_type=result_primitive_type,
    )
    if final_blend_mode in {"subtract", "intersect"}:
        _with_boolean_seam(
            record,
            op=op,
            operation=final_blend_mode,
            seam_group=_seam_group_name(op, f"{_op_tag_token(op.op)}_compound_seam"),
        )
    return record


