def _refine_kernel_record_for_source(
    op: ShapeOp,
    *,
    source_record: _V1Record,
    geometry_kernel: Any,
    operation: str,
    modifier_name: str,
    modifier_payload: dict[str, Any],
    result_primitive_type: str,
    kernel_tag: str,
    refine_levels: int | None = None,
    refine_scheme: str | None = None,
    refine_target_edge_length_cm: float | None = None,
    refine_mode: str = "adaptive",
    refine_max_iterations: int = 6,
) -> _V1Record:
    from ..geometry.shape_ir_lowering import execute_shape_ir_kernel_program

    part = str(op.target or source_record.get("part") or operation.replace(".", "_"))
    blend_mode = _optional_blend_mode(
        op.parameters,
        default=str(source_record.get("blend_mode") or "union"),
    )
    result = execute_shape_ir_kernel_program(
        geometry_kernel,
        _shape_ir_for_kernel_records(
            (
                _record_with_kernel_semantic_metadata(
                    op,
                    source_record,
                    blend_mode=blend_mode,
                ),
            ),
            asset_name=f"shape_ir_v2_{op.op.replace('.', '_')}_source",
            blueprint_id=f"shape_ir_v2_{op.op.replace('.', '_')}_source",
        ),
        program_kind=operation,
        source_index=0,
        semantic_operation=operation,
        refine_operation=operation,
        refine_levels=refine_levels,
        refine_scheme=refine_scheme,
        refine_target_edge_length_cm=refine_target_edge_length_cm,
        refine_mode=refine_mode,
        refine_max_iterations=refine_max_iterations,
        route=f"shape_ir_v2_{op.op.replace('.', '_')}",
    )
    details = dict(result.details)
    modifier = {
        **modifier_payload,
        "source_part": str(source_record.get("part") or ""),
        "source_primitive_type": str(source_record.get("primitive_type") or ""),
        **_source_context_operation_payload(
            source_record,
            metadata_key="v2_refine_context",
        ),
    }
    for detail_key, modifier_key in (
        ("refine_source_face_count", "source_face_count"),
        ("refine_source_vertex_count", "source_vertex_count"),
        ("refine_result_face_count", "result_face_count"),
        ("refine_result_vertex_count", "result_vertex_count"),
        ("refine_result_watertight", "result_watertight"),
        ("levels", "levels"),
        ("requested_scheme", "requested_scheme"),
        ("actual_scheme", "actual_scheme"),
        ("method", "method"),
        ("actual_method", "actual_method"),
        ("target_edge_length_cm", "target_edge_length_cm"),
        ("requested_mode", "requested_mode"),
        ("max_iterations", "max_iterations"),
        ("smoothing", "smoothing"),
    ):
        if detail_key in details:
            modifier[modifier_key] = _metadata_safe_value(details[detail_key])

    record = _kernel_mesh_record_for_result(
        op,
        result=result,
        part=part,
        tags=[
            *list(source_record.get("tags") or []),
            kernel_tag,
            "kernel_refine_program",
        ],
        blend_mode=blend_mode,
        modifier_name=modifier_name,
        modifier_payload=modifier,
        geometry_kernel=geometry_kernel,
        source_records=(source_record,),
        kernel_selection=_kernel_selection_source(geometry_kernel),
        result_primitive_type=result_primitive_type,
    )
    record["v2_source_op"] = source_record.get("v2_op")
    semantic_metadata = dict(record.get("semantic_metadata") or {})
    semantic_metadata["operation"] = operation
    semantic_metadata["operation_id"] = f"{op.op}:{part}:{source_record.get('part') or 'source'}"
    semantic_metadata["refine"] = _metadata_safe_value(modifier)
    record["semantic_metadata"] = semantic_metadata
    return record


