def lower_to_v1(
    program: ShapeProgram,
    *,
    geometry_kernel: Any | None = None,
    materialize_output: bool = True,
) -> V1AdapterResult:
    """Lower a ShapeProgram while scoping kernel-aware ops to ``geometry_kernel``."""
    token = _LOWERING_GEOMETRY_KERNEL.set(geometry_kernel)
    try:
        return _lower_to_v1_with_context(
            program,
            geometry_kernel=geometry_kernel,
            materialize_output=materialize_output,
        )
    finally:
        _LOWERING_GEOMETRY_KERNEL.reset(token)


def _lower_to_v1_with_context(
    program: ShapeProgram,
    *,
    geometry_kernel: Any | None = None,
    materialize_output: bool = True,
) -> V1AdapterResult:
    """Lower a :class:`ShapeProgram` to v1-compatible records.

    Walks ``program.ops`` in declaration order. For each op:

    - If the op name is not a member of :data:`ALL_OPS`, emit an
      ``unsupported_v2_op`` diagnostic and record the op name in
      ``unsupported_ops``. No v1 record is produced.
    - If any required parameter is absent, emit one
      ``missing_required_param`` diagnostic per missing key and skip
      the v1 record.
    - If the op is a v1-lowerable solid, produce the corresponding v1
      primitive record.
    - If a lowerable op carries a present but non-numeric dimension,
      emit ``parameter_type_mismatch`` and skip the v1 record.
    - Otherwise the op is valid in v2 but has no v1 primitive or
      source-preserving modifier equivalent: emit a ``no_v1_equivalent``
      diagnostic. The op is recorded for Phase 6/7+ consumers; no v1
      record is produced.

    Determinism: identical inputs always yield identical outputs;
    operation order is preserved.
    """
    v1_records: list[dict[str, Any]] = []
    diagnostics: list[dict[str, Any]] = []
    unsupported_ops: list[str] = []
    seen_unsupported: set[str] = set()
    source_context: dict[str, _V1Record] = {}

    for op_index, op in enumerate(program.ops):
        if op.op not in ALL_OPS:
            diagnostics.append(
                {
                    "code": "unsupported_v2_op",
                    "op": op.op,
                    "reason": (
                        f"op '{op.op}' is not a member of any ShapeIR v2 "
                        "operation family"
                    ),
                }
            )
            if op.op not in seen_unsupported:
                unsupported_ops.append(op.op)
                seen_unsupported.add(op.op)
            continue

        op = _with_contextual_target(
            _with_contextual_source(op, source_context),
            source_context,
        )
        required = _REQUIRED_PARAMS.get(op.op, ())
        parameters = op.parameters if isinstance(op.parameters, dict) else {}
        missing = [
            key
            for key in required
            if not _has_required_param_alias(op.op, parameters, key)
        ]
        if missing:
            for key in missing:
                diagnostics.append(
                    {
                        "code": "missing_required_param",
                        "op": op.op,
                        "reason": f"required parameter '{key}' is absent",
                    }
            )
            continue

        lowerer = _V1_LOWERERS.get(op.op)
        if lowerer is None:
            diagnostics.append(
                {
                    "code": "no_v1_equivalent",
                    "op": op.op,
                    "reason": (
                        f"op '{op.op}' is valid in ShapeIR v2 but has no "
                        "v1 primitive equivalent"
                    ),
                }
            )
            continue

        try:
            lowered_records = _normalize_lowering(
                _lower_op_to_v1(op, lowerer, geometry_kernel=geometry_kernel)
            )
        except (TypeError, ValueError) as exc:
            diagnostics.append(_lowering_exception_diagnostic(op, exc))
            continue

        lowered_records = tuple(
            _promote_v2_provenance(
                record,
                op_index=op_index,
                record_index=record_index,
            )
            for record_index, record in enumerate(lowered_records)
        )
        source_context_keys: list[str] = []
        raw_source_context_keys = parameters.get("source_context_keys")
        if isinstance(raw_source_context_keys, (list, tuple)):
            for key in raw_source_context_keys:
                text = str(key or "").strip()
                if text and text not in source_context_keys:
                    source_context_keys.append(text)
        source_context_key = str(parameters.get("source_context_key") or "").strip()
        if source_context_key and source_context_key not in source_context_keys:
            source_context_keys.append(source_context_key)
        should_replace_contextual_sources = bool(source_context_keys) and _should_replace_contextual_source_records(
            op,
            geometry_kernel=geometry_kernel,
        )
        replaced_context_aliases: list[str] = []
        if should_replace_contextual_sources:
            for key in source_context_keys:
                replaced_context_aliases.extend(
                    _replace_contextual_source_records(
                        v1_records,
                        source_context,
                        key=key,
                    )
                )
        target_context_key = str(parameters.get("target_context_key") or "")
        if (
            op.op in _TARGET_REPLACEMENT_OPS
            and target_context_key
        ):
            replaced_context_aliases.extend(
                _replace_contextual_source_records(
                    v1_records,
                    source_context,
                    key=target_context_key,
                )
            )
        v1_records.extend(lowered_records)
        for record in lowered_records:
            _register_source_context(record, source_context)
            _register_source_context_alias(record, source_context, key=op.target)
            if should_replace_contextual_sources or replaced_context_aliases:
                for key in [*source_context_keys, *replaced_context_aliases]:
                    _register_source_context_alias(record, source_context, key=key)

    final_records = tuple(v1_records)
    if geometry_kernel is not None and materialize_output:
        try:
            final_records = _materialize_v1_records_with_kernel(
                final_records,
                program=program,
                geometry_kernel=geometry_kernel,
            )
        except (TypeError, ValueError) as exc:
            diagnostics.append(_lowering_exception_diagnostic(
                ShapeOp(
                    op="shape_ir_v2.output_materialize",
                    target=program.asset_name or "shape_ir_v2_output",
                    parameters={},
                    purpose="shape_ir_v2.output_materialize",
                ),
                exc,
            ))

    return V1AdapterResult(
        v1_records=final_records,
        diagnostics=tuple(diagnostics),
        unsupported_ops=tuple(unsupported_ops),
    )
